function startQuickTrace(type,roof=false){if(view3d)setMapView(false);const selector=$('ztype');if(selector)selector.value=type;traceStart();if(!tr.on)return;tr.roof=!!roof;tr.manualSession=true;const choices=$('quickTraceChoices'),actions=$('quickTraceActions'),status=$('quickTraceStatus');if(choices)choices.hidden=true;if(actions)actions.hidden=false;if(status)status.textContent='Click near the green start point to close this outline and begin another, or choose Finish Outline when done.';hint('Map edit: click near the green start point to close this outline and start another. Choose Finish Outline when done.')}
function startManualLawn(){const p=cur();if(!p.lat)return toast('Find the property before drawing the lawn');p.zones=[];p.visionCandidates=[];delete p.visionSummary;delete p.mapReviewCompleteAt;p.visionMessage='AI outlines and previous hand-drawn zones cleared. Trace the mowable lawn, closing each area near its starting point.';p.useParcelMow=false;p.manualMowOverride=true;const mappedHouse=(p.obstacles||[]).some(o=>o.kind==='building'&&o.status!=='rejected'&&o.pts?.length>=3&&areaFt(o.pts)>=400);p.houseMissing=!mappedHouse;p.roofConfirmed=mappedHouse;tr={on:false,pts:[],lay:null,roof:false};save();render();const selector=$('ztype');if(selector)selector.value='mow';const slope=$('zslope');if(slope)slope.value='Flat';traceStart();if(!tr.on)return;tr.manualReplacement=true;tr.manualSession=true;const choices=$('quickTraceChoices'),actions=$('quickTraceActions'),status=$('quickTraceStatus');if(choices)choices.hidden=true;if(actions)actions.hidden=false;if(status)status.textContent='Click near the green start point to close this lawn and begin another area. Choose Finish Outline when done.';hint('Manual lawn: close each area by clicking near its green start point. Choose Finish Outline when done.')}
function plannedAreaSummary(p){
 const plan=cutPlan(p);if(typeof turf==='undefined')return{mow:null,weed:null,draft:!!plan.draft};
 try{const combine=zones=>{let result=null;for(const z of zones){const ring=closedLngLat(z.pts||[]);if(!ring)continue;const polygon=turf.polygon([ring]);result=result?turf.union(result,polygon):polygon}return result};
 const subtract=(shape,zones)=>{for(const z of zones){if(!shape)break;const ring=closedLngLat(z.pts||[]);if(ring)shape=turf.difference(shape,turf.polygon([ring]))}return shape};
 const excluded=passExclusions(p),hard=excluded.filter(z=>z.kind!=='weed');
 let mow=plan.draft&&p.parcel?turf.feature(p.parcel):combine(plan.zones||[]);mow=subtract(mow,excluded);
 let weed=combine((p.zones||[]).filter(z=>z.type==='weed'));if(weed&&p.parcel)weed=turf.intersect(weed,turf.feature(p.parcel));weed=subtract(weed,hard);
 return{mow:mow?Math.round(turf.area(mow)*10.7639):0,weed:weed?Math.round(turf.area(weed)*10.7639):0,draft:!!plan.draft}
 }catch(error){console.warn('Mapped area summary unavailable',error);return{mow:null,weed:null,draft:!!plan.draft}}
}
function propertyCompletionSummaryHTML(p){const a=plannedAreaSummary(p),area=n=>n===null?'Unavailable':n.toLocaleString()+' ft²',time=(n,rate)=>n===null?'—':n===0?'0 min':'~'+(Math.ceil(n/rate)+5)+' min';return `<div class="map-area-summary"><div><span class="small">Planned mow area${a.draft?' · provisional':''}</span><strong>${area(a.mow)}</strong><span class="small">Mowing: ${Number(p.customMowMinutes)>0?p.customMowMinutes+' min · owner-set':time(a.mow,mowingAreaPerMinute())}</span></div><div><span class="small">Weed-whack area</span><strong>${area(a.weed)}</strong><span class="small">Weed-whacking: ${time(a.weed,100)}</span></div></div><p class="small map-time-note">Estimates use your saved mowing-time rate (${Number(S.set.mowingTimeMinutes)||2} min per ${(Number(S.set.mowingTimeArea)||1000).toLocaleString()} ft²) and 100 ft²/min for weed-whacking, plus 5 minutes of setup per task with a mapped area. Actual time varies with terrain, equipment, and obstacles. Mowing excludes marked weed-whack and no-cut areas.</p>`}
function completePropertyMap(){const p=cur(),plan=cutPlan(p),pinConfirmed=p.addressVerified||['manual map pin','map selection','Esri World Geocoding','US Census address ranges','county GIS','Photon','general geocoder'].includes(p.geoSource);if(!p.lat)return toast('Find the property before completing the map');if(plan.manualBoundary&&(!p.parcel||p.parcelSelectionNeedsReview)&&!pinConfirmed)return toast('The red address pin looks unconfirmed. Move it onto the correct property before saving.');if(!plan.manualBoundary&&(!p.parcel||p.parcelSelectionNeedsReview))return toast('Find the property and confirm its boundary first');if(plan.loading||plan.lookupFailed)return toast('Wait for the house check to finish, or mark the house and driveway as no-cut');if(plan.houseMissing)return toast('Mark the house as no-cut before completing the map');if(!p.zones.some(z=>z.type==='mow'&&z.pts.length>=3))return toast('Add or confirm the green lawn area before completing');if(!p.drivewayReviewed)return toast('Review the driveway and paved areas, then check the confirmation');p.mapReviewCompleteAt=new Date().toISOString();save();render();if(p.setupPending)return resumeCustomerSetup(p);toast('Property map marked complete')}
function cancelQuickTrace(){if(tr.lay&&maps.emap)maps.emap.removeLayer(tr.lay);tr={on:false,pts:[],lay:null,roof:false};const choices=$('quickTraceChoices'),actions=$('quickTraceActions');if(choices)choices.hidden=false;if(actions)actions.hidden=true;hint('')}
let historyCustomerId=null;
let historyPropertyId=null;
function filterHistory(value){historyCustomerId=null;historyPropertyId=null;if(value.startsWith('customer:'))historyCustomerId=value.slice(9);else if(value.startsWith('property:'))historyPropertyId=value.slice(9);renderHist()}
function historyFilterHTML(){const value=historyPropertyId?'property:'+historyPropertyId:historyCustomerId?'customer:'+historyCustomerId:'all';return `<label class="small">Property Filter<select aria-label="Filter mowing history by property" onchange="filterHistory(this.value)"><option value="all" ${value==='all'?'selected':''}>All properties</option>${(S.customers||[]).filter(c=>S.p.filter(p=>p.customerId===c.id).length>1).map(c=>`<option value="customer:${esc(c.id)}" ${value==='customer:'+c.id?'selected':''}>${esc(c.name)} · All properties</option>`).join('')}${S.p.map(p=>`<option value="property:${esc(p.id)}" ${value==='property:'+p.id?'selected':''}>${esc(p.name)} — ${esc(p.addr||p.street||'')}</option>`).join('')}</select></label>`}
function openCustomerHistory(index){const c=S.customers[index];if(!c)return;const properties=S.p.filter(p=>p.customerId===c.id);historyPropertyId=properties.length===1?properties[0].id:null;historyCustomerId=properties.length===1?null:c.id;renderHist();go('history',true)}
function historyRecords(){const properties=historyPropertyId?S.p.filter(p=>p.id===historyPropertyId):historyCustomerId?S.p.filter(p=>p.customerId===historyCustomerId):S.p;return properties.flatMap(p=>(p.visits||[]).map((visit,index)=>({p,visit,index}))).sort((a,b)=>String(b.visit.date).localeCompare(String(a.visit.date))||Number(b.visit.startedOn||0)-Number(a.visit.startedOn||0))}
function serviceProofHTML(v){const photo=typeof v.proofPhoto==='string'&&/^(data:image\/(?:jpeg|png|webp);base64,|https:\/\/|\/(?!\/))/.test(v.proofPhoto)?v.proofPhoto:'';return photo?`<details class="service-proof"><summary>View Completion Photo</summary><img src="${esc(photo)}" alt="Completion photo for service on ${esc(v.date)}" loading="lazy"></details>`:'<span class="small">No completion photo recorded</span>'}
function formatMowClock(value){const match=/^(\d{2}):(\d{2})$/.exec(value||'');if(!match)return '';const hour=Number(match[1]);return (hour%12||12)+':'+match[2]+(hour<12?' AM':' PM')}
function renderHist(){const c=S.customers?.find(c=>c.id===historyCustomerId),p=cur(),records=historyRecords();$('history').innerHTML=`${historyPropertyId?uxPropertyContext(S.p.find(q=>String(q.id)===String(historyPropertyId)),'history'):''}<div class="top"><div><div class="eyebrow">Service records</div><h1>${c?esc(c.name)+' · Service History':'Service History'}</h1><div class="small">${records.length} recorded ${records.length===1?'visit':'visits'}${c?' across this customer’s properties':''}</div></div><div class="topright">${c?'<button class="btn" onclick="go(\'customers\')">← Customers</button>':''}${historyFilterHTML()}${p?'<button class="btn primary" onclick="logForm()">＋ Log Service</button>':''}</div></div><div class="service-record-list">${records.map(({p,visit:v})=>`<article class="card service-record"><div class="st"><div><h2>${esc(p.name)}</h2><div class="small">${esc(p.addr||p.street)}</div></div><strong>${dt(v.date)}${v.serviceTime?' · '+esc(formatMowClock(v.serviceTime)):''}</strong></div><div class="service-record-metrics"><div><span class="small">Duration</span><strong>${Number(v.time)||0} min${v.timed?' · timed':' · entered'}</strong></div><div><span class="small">Cut height</span><strong>${esc(v.height||'—')}</strong></div><div><span class="small">Pattern</span><strong>${esc(v.pattern||'—')}</strong></div></div>${v.mowerSetting?`<p class="small">Mower setting: ${esc(v.mowerSetting)}</p>`:''}${v.notes?`<p class="small">${esc(v.notes)}</p>`:''}${serviceProofHTML(v)}</article>`).join('')||'<div class="card"><h2>No Mowing Records Yet</h2><p class="small">Completed services and their proof photos will appear here.</p></div>'}</div>`}
function delVisit(i){cur().visits.splice(i,1);save();render();toast('Visit deleted')}
function mappingReady(p){if(!p)return false;const located=p.lat!==null&&p.lat!==undefined&&p.lat!==''&&p.lng!==null&&p.lng!==undefined&&p.lng!==''&&Number.isFinite(+p.lat)&&Number.isFinite(+p.lng)&&Math.abs(+p.lat)<=90&&Math.abs(+p.lng)<=180;const lawn=(p.zones||[]).some(z=>z.type==='mow'&&Array.isArray(z.pts)&&z.pts.length>=3);return !!(located&&(p.mapReviewCompleteAt||lawn||(p.parcel&&!p.parcelSelectionNeedsReview)))}
function linkCustomerRecords(){S.customers=Array.isArray(S.customers)?S.customers:[];for(const p of S.bp){let c=S.customers.find(c=>c.id===p.customerId);if(!c){c=p.email?S.customers.find(c=>c.email&&c.email.toLowerCase()===p.email.toLowerCase()):null;if(!c){c={id:'customer-'+p.id,name:p.customerName||p.name,email:p.email||'',phone:p.phone||'',billingAddress:p.billingAddress||''};S.customers.push(c)}p.customerId=c.id}p.customerName=c.name}}
function customerForProperty(p){return S.customers?.find(c=>c.id===p.customerId)}
function customerFieldsHTML(c={}){return `<label>Customer Name *<input id="c_n" required value="${esc(c.name||'')}" autocomplete="name"></label><label>Email<input id="c_e" type="email" value="${esc(c.email||'')}"></label><label>Phone<input id="c_phone" type="tel" value="${esc(c.phone||'')}"></label><details class="signup-billing" ${c.billingAddress?'open':''}><summary>Use a Different Billing Address</summary><p class="small">Otherwise, billing uses the service address you enter next.</p><label>Billing Address<input id="c_billing" value="${esc(c.billingAddress||'')}" autocomplete="billing street-address" placeholder="Enter only if different"></label></details>`}
function propertyCustomerChoice(){const existing=$('c_customer')?.value;const fields=$('new_customer_fields');if(fields){fields.hidden=!!existing;fields.querySelectorAll('input').forEach(input=>input.disabled=!!existing)}}
function editCustomerDetails(index){const c=S.customers[index];openM(`<h2>Edit Customer</h2><form onsubmit="event.preventDefault();saveCustomerDetails(${index})"><div class="form">${customerFieldsHTML(c)}</div><div class="actions"><button type="button" class="btn" onclick="closeM()">Cancel</button><button class="btn primary">Save Customer</button></div></form>`)}
function saveCustomerDetails(index){const c=S.customers[index],name=$('c_n').value.trim();if(!name)return toast('Enter a customer name');Object.assign(c,{name,email:$('c_e').value.trim(),phone:$('c_phone').value.trim(),billingAddress:$('c_billing').value.trim()});S.p.filter(p=>p.customerId===c.id).forEach(p=>Object.assign(p,{customerName:c.name,email:c.email,phone:c.phone,billingAddress:c.billingAddress}));save();closeM();render();toast('Customer updated')}
function confirmDeleteCustomer(index){const c=S.customers[index];if(!c)return;const properties=S.p.filter(p=>p.customerId===c.id);openM(`<h2>Delete Customer?</h2><p>Remove ${esc(c.name)} and ${properties.length} linked ${properties.length===1?'property':'properties'} from your workspace? Their maps and history will be archived so you can restore them.</p><div class="actions"><button class="btn" onclick="closeM()">Cancel</button><button class="btn customer-delete" onclick="deleteCustomer(${index})">Delete Customer</button></div>`)}
function deleteCustomer(index){const c=S.customers[index];if(!c)return;const properties=S.p.filter(p=>p.customerId===c.id);if(S.activeCut&&properties.some(p=>String(p.id)===String(S.activeCut.propertyId)))return toast('Finish or cancel the active cut before deleting this customer');S.archivedCustomers=Array.isArray(S.archivedCustomers)?S.archivedCustomers:[];S.archivedCustomers.push({customer:c,properties,deletedAt:new Date().toISOString()});S.deletedPropertyIds=[...new Set([...(S.deletedPropertyIds||[]),...properties.map(p=>String(p.id))])];const selected=cur()?.id;S.bp=S.bp.filter(p=>p.customerId!==c.id);S.customers.splice(index,1);S.sel=Math.max(0,S.bp.findIndex(p=>p.id===selected));save();closeM();render();toast('Customer deleted. Restore is available in Customers.')}
function restoreDeletedCustomer(){const archive=S.archivedCustomers?.pop();if(!archive)return;S.customers.push(archive.customer);S.bp.push(...archive.properties);const restored=new Set(archive.properties.map(p=>String(p.id)));S.deletedPropertyIds=(S.deletedPropertyIds||[]).filter(id=>!restored.has(String(id)));save();render();toast('Customer and properties restored')}
function estimateForm(index=S.sel){if(!S.p.length)return custForm('customer');openM(`<h2>Map a Property & Estimate</h2><p class="small">Choose a property, map its lawn, then review its price.</p><div class="form"><label>Customer / Property<select id="estimate_property">${S.p.map((p,i)=>`<option value="${i}" ${i===index?'selected':''}>${esc(customerForProperty(p)?.name||p.customerName||p.name)} · ${esc(p.name)}</option>`).join('')}</select></label></div><div class="actions"><button class="btn" onclick="custForm('customer')">New Customer & Property</button><button class="btn" onclick="closeM()">Cancel</button><button class="btn primary" onclick="openEstimateMap()">Map & Estimate</button></div>`)}
function openEstimateMap(){const index=+$('estimate_property').value;if(!S.p[index])return;closeM();pick(index);go('map')}
function mappedMowingPrice(p){const rate=Number(S.set.mowingRate),unit=Number(S.set.mowingRateArea)||1000,a=plannedAreaSummary(p);if(!(rate>0&&unit>0&&a.mow>0))return null;return Math.round(a.mow/unit*rate*100)/100}
const MOW_FREQUENCIES={weekly:'Once a week',twiceWeekly:'Twice a week',threeWeekly:'Three times a week',biweekly:'Every Two Weeks',monthly:'Once a month',asNeeded:'As needed'};
function mowingFrequency(p){return MOW_FREQUENCIES[p.mowingFrequency]||MOW_FREQUENCIES.weekly}
function frequencySelectorHTML(p,index){return `<label class="customer-frequency">Mowing Frequency<select aria-label="Mowing frequency for ${esc(p.name)}" onchange="saveMowingFrequency(${index},this.value)" ${isOwner()?'':'disabled'}>${Object.entries(MOW_FREQUENCIES).map(([value,label])=>`<option value="${value}" ${(p.mowingFrequency||'weekly')===value?'selected':''}>${label}</option>`).join('')}</select></label>`}
function propertyNotesHTML(p,index,prefix=''){return `<details class="property-service-notes" ${p.serviceNotes?'open':''}><summary>Property notes${p.serviceNotes?'':' · Add notes'}</summary>${isOwner()?`<form onsubmit="event.preventDefault();savePropertyNotes(${index},'${prefix}')"><label class="small" for="${prefix}property_notes_${index}">Access Instructions, Gate Codes, Pets, and Areas to Avoid</label><textarea id="${prefix}property_notes_${index}" rows="3" maxlength="5000" placeholder="Add instructions for the crew…">${esc(p.serviceNotes||'')}</textarea><div class="actions"><button class="btn sm" type="submit">Save Notes</button><span class="small" id="${prefix}property_notes_status_${index}" aria-live="polite"></span></div></form>`:`<p class="small">${esc(p.serviceNotes||'No property notes yet.')}</p>`}</details>`}
function savePropertyNotes(index,prefix=''){if(!isOwner()||!S.p[index])return;const input=$(prefix+'property_notes_'+index);if(!input)return;S.p[index].serviceNotes=input.value.trim().slice(0,5000);save();const status=$(prefix+'property_notes_status_'+index);if(status)status.textContent='Saved';toast('Property notes saved')}
function crewPropertyNotesHTML(p){return p.serviceNotes?`<div class="crew-property-notes"><strong>Property instructions</strong><p>${esc(p.serviceNotes)}</p></div>`:''}
function schedulingControlsHTML(p,index){return `<label class="customer-frequency">First Service Date<input type="date" value="${esc(p.firstServiceDate||today())}" onchange="saveSchedulingStart(${index},this.value)"></label><label class="customer-auto-schedule"><input type="checkbox" ${p.autoSchedule!==false?'checked':''} onchange="saveAutoScheduling(${index},this.checked)"> Automatically schedule mows</label>`}
function resetPropertySchedule(p){for(const plan of Object.values(S.weekPlans||{})){if(plan.slots)delete plan.slots[String(p.id)];if(plan.days)delete plan.days[String(p.id)]}rt=null;rsel=null}
function saveSchedulingStart(index,date){if(!isOwner()||!S.p[index]||!/^\d{4}-\d{2}-\d{2}$/.test(date))return;const p=S.p[index];p.firstServiceDate=date;p.frequencyAnchor=date;resetPropertySchedule(p);save();toast('First service date saved')}
function saveAutoScheduling(index,enabled){if(!isOwner()||!S.p[index])return;const p=S.p[index];p.autoSchedule=!!enabled;resetPropertySchedule(p);save();toast(enabled?'Automatic scheduling enabled':'Use Add Mow Event to schedule this property')}
function serviceDaySelectorHTML(p,index){return `<label class="customer-frequency">Preferred Service Day<select aria-label="Preferred service day for ${esc(p.name)}" onchange="saveCustomerServiceDay(${index},this.value)" ${isOwner()?'':'disabled'}><option value="auto" ${p.serviceDay==null?'selected':''}>Automatic</option>${DAY.map((day,d)=>`<option value="${d}" ${p.serviceDay===d?'selected':''}>${day}</option>`).join('')}</select></label>`}
function saveCustomerServiceDay(index,value){if(!isOwner()||!S.p[index])return;const day=value==='auto'?null:Number(value);if(day!==null&&(!Number.isInteger(day)||day<0||day>6))return;const p=S.p[index];p.serviceDay=day;for(const plan of Object.values(S.weekPlans||{})){if(plan.slots)delete plan.slots[String(p.id)];if(plan.days)delete plan.days[String(p.id)]}rt=null;rsel=null;save();toast('Preferred service day saved')}
function saveMowingFrequency(index,value){if(!isOwner()||!MOW_FREQUENCIES[value]||!S.p[index])return;S.p[index].mowingFrequency=value;S.p[index].frequencyAnchor=monday(today());for(const plan of Object.values(S.weekPlans||{})){if(plan.slots)delete plan.slots[String(S.p[index].id)];if(plan.days)delete plan.days[String(S.p[index].id)]}rt=null;rsel=null;save();renderRoute();toast('Mowing frequency saved')}
function mapTimeEstimateHTML(p){const a=plannedAreaSummary(p),automatic=calculatedTaskMinutes(a.mow,mowingAreaPerMinute()),custom=Number(p.customMowMinutes)>0;return `<div class="map-estimate-panel"><div class="st"><h2>Estimated Mowing Time</h2>${B(custom?'Owner-set time':'Automatic estimate')}</div><div class="sl"><span>Calculated from planned mow area</span><strong>${a.mow>0?automatic+' min':'Map the lawn first'}</strong></div><p class="small">Uses your Settings rate: ${Number(S.set.mowingTimeMinutes)||2} minutes per ${(Number(S.set.mowingTimeArea)||1000).toLocaleString()} ft², plus 5 minutes of setup. Weed-whacking is estimated separately and included in the total service time.</p>${isOwner()?`<form class="map-estimate-form" onsubmit="event.preventDefault();saveMowingTime()"><label>Mowing Time (Minutes)<input id="map_mow_minutes" type="number" min="1" max="1440" step="1" required value="${custom?p.customMowMinutes:automatic||''}"></label><button class="btn" type="submit">Save Time</button><button class="btn" type="button" onclick="resetMowingTime()">Use Automatic Time</button></form>`:''}<div class="sl"><span>Total estimated service time · mowing + weed-whacking</span><strong>${eta(p)>0?eta(p)+' min':'—'}</strong></div></div>`}
function saveMowingTime(){if(!isOwner())return;const value=Number($('map_mow_minutes').value);if(!Number.isInteger(value)||value<1||value>1440)return toast('Enter a mowing time between 1 and 1,440 minutes');cur().customMowMinutes=value;save();render();toast('Mowing time saved')}
function resetMowingTime(){if(!isOwner())return;delete cur().customMowMinutes;save();render();toast('Using automatic mowing time')}
function mapEstimateHTML(p){const calculated=mappedMowingPrice(p),a=plannedAreaSummary(p),custom=Number(p.customPrice)>0,owner=isOwner();return `<div class="map-estimate-panel"><div class="st"><h2>Mowing Estimate</h2>${B(custom?'Owner price':'Calculated price')}</div><div class="sl"><span>Based on planned mow area${a.draft?' · provisional':''}</span><strong>${calculated===null?'—':'$'+calculated.toFixed(2)+' / visit'}</strong></div><p class="small">${Number(S.set.mowingRate)>0?'$'+Number(S.set.mowingRate).toFixed(2)+' per '+(Number(S.set.mowingRateArea)||1000).toLocaleString()+' ft² of planned mowing. Weed-whacking and other services are not included.':'Set your mowing rate in Settings to calculate an estimate.'}${!a.mow?' Map the lawn to calculate its price.':''}</p>${owner?`<form class="map-estimate-form" onsubmit="event.preventDefault();saveMapPrice()"><label>Price per Visit ($)<input id="map_estimate_price" type="number" min="0.01" step="0.01" value="${custom?Number(p.customPrice).toFixed(2):calculated??''}" placeholder="Enter your price" required></label><button class="btn" type="submit">Save Price</button><button class="btn" type="button" onclick="resetMapPrice()" ${calculated===null?'disabled':''}>Use Calculated Price</button><button class="btn primary" type="button" onclick="saveMapEstimate()">Save Estimate Draft</button></form><p class="small">A saved price applies to future invoices for this property. Existing invoices stay unchanged.</p>`:`<div class="sl"><span>Price per visit</span><strong>${custom?'$'+Number(p.customPrice).toFixed(2):calculated===null?'—':'$'+calculated.toFixed(2)}</strong></div>`}</div>`}
function saveMapPrice(){if(!isOwner())return;const input=$('map_estimate_price'),price=Number(input?.value);if(!Number.isFinite(price)||price<=0){toast('Enter a price greater than zero');return false}cur().customPrice=price;cur().paymentPricing='include';save();render();toast('Property price saved');return true}
function resetMapPrice(){if(!isOwner()||mappedMowingPrice(cur())===null)return;delete cur().customPrice;cur().useMappedPrice=true;save();render();toast('Using calculated mowing price')}
function saveMapEstimate(){if(!isOwner())return;const price=Number($('map_estimate_price')?.value),p=cur();if(!Number.isFinite(price)||price<=0)return toast('Enter a price greater than zero');p.customPrice=price;p.paymentPricing='include';S.estimates=Array.isArray(S.estimates)?S.estimates:[];S.estimates.push({id:crypto.randomUUID(),customerId:p.customerId,propertyId:p.id,propertyName:p.name,price,notes:'Mowing estimate based on mapped lawn. Other services excluded.',mowArea:plannedAreaSummary(p).mow,status:'draft',createdAt:new Date().toISOString()});save();render();toast('Estimate draft and property price saved')}
function updateEstimatePreview(){const p=S.p[+$('estimate_property').value];if(!p)return;$('estimate_price').value=priceFor(p);$('estimate_details').innerHTML=`<div class="small">${esc(p.addr||p.street)}<br>${(+p.sqft||0).toLocaleString()} ft² recorded · Suggested price: $${priceFor(p)} per visit${!p.sqft?' · Map the lawn before finalizing the price.':''}</div>`}
function saveEstimateDraft(){const p=S.p[+$('estimate_property').value],price=Number($('estimate_price').value);if(!p||!Number.isFinite(price)||price<=0)return toast('Enter a valid price');S.estimates=Array.isArray(S.estimates)?S.estimates:[];S.estimates.push({id:crypto.randomUUID(),customerId:p.customerId,propertyId:p.id,propertyName:p.name,price,notes:$('estimate_notes').value.trim(),status:'draft',createdAt:new Date().toISOString()});save();closeM();toast('Estimate draft saved')}
function renderCust(){linkCustomerRecords();$('customers').innerHTML=`<div class="top"><div><div class="eyebrow">Customer management</div><h1>Customers</h1><p class="small">Manage contact and billing details here. Map each service location in Property Map.</p></div><div class="actions">${S.archivedCustomers?.length?'<button class="btn" onclick="restoreDeletedCustomer()">Restore Last Deleted</button>':''}<button class="btn primary" onclick="custForm('customer')">＋ Add Customer</button></div></div>${BIZ_ACCOUNT&&isOwner()?`<div class="card customer-signup-card">${customerSignupSectionHTML()}</div>`:''}<div class="customer-records">${S.customers.map((c,ci)=>{const properties=S.p.map((p,i)=>({p,i})).filter(x=>x.p.customerId===c.id);return `<article class="card"><div class="st"><div><h2>${esc(c.name)}</h2><div class="small">${esc(c.email||'No email')} · ${esc(c.phone||'No phone')}</div></div><div class="actions"><button class="btn sm" onclick="editCustomerDetails(${ci})">Edit Customer</button><button class="btn sm" type="button" onclick="openCustomerBilling(${ci})">Manage Billing</button><button class="btn sm" onclick="openCustomerHistory(${ci})">Mowing History</button><button class="btn sm" onclick="custForm('property',${ci})">＋ Add Property</button><button class="btn sm customer-delete" onclick="confirmDeleteCustomer(${ci})">Delete Customer</button></div></div>${(S.estimates||[]).filter(e=>e.customerId===c.id).length?`<details class="customer-estimates"><summary>Estimate Drafts</summary>${(S.estimates||[]).filter(e=>e.customerId===c.id).map(e=>`<div class="sl"><span>${esc(e.propertyName)}<br><span class="small">${esc(e.notes||'Draft estimate')}</span></span><strong>$${Number(e.price).toFixed(2)} / visit</strong></div>`).join('')}</details>`:''}<div class="customer-properties">${properties.map(({p,i})=>`<div class="customer-property-row"><div class="customer-property-address">${p.name.trim().toLowerCase()!==c.name.trim().toLowerCase()?`<strong>${esc(p.name)}</strong>`:''}<div class="small">${esc(p.addr||p.street||'Address not set')}</div><span class="small">${p.sqft>0?(+p.sqft).toLocaleString()+' ft²':'Area not measured'}</span></div><div class="customer-property-price"><span class="small">Service amount</span><strong>$${Number(priceFor(p)).toFixed(2)}</strong><span class="small">Customer total: $${propertyInvoicePricing(p).amt.toFixed(2)}</span><span class="small">${Number(p.customPrice)>0?'Owner-set':mappedMowingPrice(p)!==null?'Mapped lawn':'Default price'}</span></div><div class="customer-property-time"><span class="small">Mowing time</span><strong>${mowingMinutes(p)>0?mowingMinutes(p)+' min':'—'}</strong><span class="small">${Number(p.customMowMinutes)>0?'Owner-set':'Estimated'}</span></div><div class="customer-schedule-preferences">${frequencySelectorHTML(p,i)}${serviceDaySelectorHTML(p,i)}${schedulingControlsHTML(p,i)}</div><div class="customer-property-map">${mappingReady(p)?B('Mapped'):B('Needs mapping','w')}<button class="btn" onclick="pick(${i});go('map')">${mappingReady(p)?'Open Map':'Open Map'}</button><button class="btn" onclick="openPropertyHealth(${i})">Lawn Health${p.probs.filter(x=>!x.done).length?' · '+p.probs.filter(x=>!x.done).length:''}</button></div>${propertyNotesHTML(p,i)}</div>`).join('')||'<p class="small">No properties yet. Add a service location to start mapping.</p>'}</div></article>`}).join('')||`<div class="card"><h2>No Customers Yet</h2><p class="small">Add a customer and their first property to get started.</p><button class="btn primary" onclick="custForm('customer')">Add Customer</button></div>`}</div><div class="customer-estimate-bar"><div><strong>Provide an Estimate</strong><div class="small">Prepare a price for a customer's property.</div></div><button class="btn primary" onclick="estimateForm()">Create Estimate</button></div>`;uxCustomers()}
function customerRecord(){return CUSTOMER_ACCOUNT?.property||null}
function normalizeCustomerAccount(c){if(!c||typeof c!=='object')return null;const source=(c.customer&&typeof c.customer==='object')?c.customer:c;const raw=source.property&&typeof source.property==='object'?source.property:source;const p={...raw};p.visits=Array.isArray(p.visits)?p.visits:[];p.inv=Array.isArray(p.inv)?p.inv:[];p.msgs=Array.isArray(p.msgs)?p.msgs:[];p.zones=Array.isArray(p.zones)?p.zones:[];p.obstacles=Array.isArray(p.obstacles)?p.obstacles:[];p.probs=Array.isArray(p.probs)?p.probs:[];p.street=p.street||p.addr||'';p.addr=p.addr||p.street||'';p.billingAddress=p.billingAddress||p.street||'';p.invoicePreference=p.invoicePreference||'Email';p.serviceNotes=p.serviceNotes||'';p.sqft=Number.isFinite(Number(p.sqft))?Number(p.sqft):0;return{property:p}}
function customerSignupHTML(){return`<div class="top"><div><div class="eyebrow">${esc(bizName())} customer portal</div><h1>Request Lawn Service</h1></div></div><div class="grid two"><div class="card"><h2>Tell Us About You</h2><div class="form"><label>Full Name *<input id="cu_name" autocomplete="name" placeholder="Jordan Smith"></label><label>Email *<input id="cu_email" type="email" autocomplete="email" placeholder="jordan@example.com"></label><label>Phone<input id="cu_phone" type="tel" autocomplete="tel" placeholder="(330) 555-0123"></label><label>Service Address *<input id="cu_addr" autocomplete="street-address" placeholder="123 Elm St, Macedonia, OH 44056"></label><label>Billing Address<select id="cu_bill_same" onchange="toggleBillingFields()"><option value="same">Same as service address</option><option value="different">Different billing address</option></select></label><div id="cu_bill_fields" style="display:none"><label>Billing Street<input id="cu_bill_addr" autocomplete="billing street-address"></label><div class="grid three"><label>City<input id="cu_bill_city" autocomplete="billing address-level2"></label><label>State<input id="cu_bill_state" maxlength="2" autocomplete="billing address-level1"></label><label>ZIP<input id="cu_bill_zip" inputmode="numeric" autocomplete="billing postal-code"></label></div></div><label>Invoice Delivery<select id="cu_pref"><option>Email</option><option>Email + payment link</option></select></label><label>Gate / Access / Lawn Notes<textarea id="cu_notes" rows="3" placeholder="Gate code location, pets, areas to avoid, preferred day, etc."></textarea></label><label><span><input id="cu_ok" type="checkbox" style="width:auto"> I confirm this information is correct and I can receive service/billing messages at the contact information above.</span></label></div><div class="actions"><button class="btn primary" onclick="submitCustomerIntake()">Create Customer Account</button></div></div><div class="card"><h2>What Happens Next</h2><div class="sl"><span>1. Property setup</span><strong>Address + parcel mapping</strong></div><div class="sl"><span>2. Lawn price</span><strong>Based on mapped mow area</strong></div><div class="sl"><span>3. Weekly service</span><strong>Added to route schedule</strong></div><div class="sl"><span>4. Billing</span><strong>Invoice after completed job</strong></div><p class="small" style="margin-top:14px">TurfOS does not store credit-card or bank numbers in this browser. Online payments use the lawn company's secure payment link.</p></div></div>`}
function toggleBillingFields(){const e=$('cu_bill_fields'),s=$('cu_bill_same');if(e&&s)e.style.display=s.value==='different'?'block':'none'}
async function submitCustomerIntake(){const name=$('cu_name').value.trim(),email=$('cu_email').value.trim(),phone=$('cu_phone').value.trim(),addr=$('cu_addr').value.trim(),same=$('cu_bill_same').value==='same',billingAddress=same?addr:$('cu_bill_addr').value.trim(),billingCity=same?'':$('cu_bill_city').value.trim(),billingState=same?'':$('cu_bill_state').value.trim().toUpperCase(),billingZip=same?'':$('cu_bill_zip').value.trim(),invoicePreference=$('cu_pref').value,serviceNotes=$('cu_notes').value.trim();if(!name||!email||!addr)return toast('Name, email, and service address are required');if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email))return toast('Enter a valid email address');if(!$('cu_ok').checked)return toast('Confirm the contact information first');let p=S.bp.find(x=>x.email&&x.email.toLowerCase()===email.toLowerCase()&&String(x.addr||x.street).toLowerCase()===addr.toLowerCase());if(!p){p={id:Date.now(),name,email,phone,street:addr,addr,sqft:0,zones:[],obstacles:[],visits:[],probs:[],inv:[],msgs:[],autoInvoice:true,billingAddress,billingCity,billingState,billingZip,invoicePreference,serviceNotes,customerPortalId:'CUST-'+Math.random().toString(36).slice(2,8).toUpperCase()};S.bp.push(p)}else Object.assign(p,{name,email,phone,billingAddress,billingCity,billingState,billingZip,invoicePreference,serviceNotes,customerPortalId:p.customerPortalId||'CUST-'+Math.random().toString(36).slice(2,8).toUpperCase()});S.customerSessionId=p.id;S.csel=S.bp.indexOf(p);save();render();toast('Customer account created');if(addr&&!p.lat){try{const r=await geo(addr);if(r){p.lat=r.lat;p.lng=r.lng;p.geoSource=r.source;await fillParcel(p);if(p.parcel)await findObstacles(p);save();render()}}catch(e){console.warn('Customer address mapping unavailable',e)}}const hook=(S.set.customerWebhook||'').trim();if(hook){try{await fetchT(hook,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({event:'customer.created',customer:{id:p.id,portalId:p.customerPortalId,name,email,phone,serviceAddress:addr,billingAddress,billingCity,billingState,billingZip,invoicePreference,serviceNotes}})},10000)}catch(e){console.warn('Customer intake webhook failed',e)}}}
function signOutCustomer(){customerLogout()}
function renderCustomer(){const e=$('customer');if(!e)return;const p=customerRecord();if(!p){e.innerHTML=customerSignupHTML();return}const next=p.nextServiceDate||null,open=p.inv.filter(v=>invoiceAmountDue(v)>0).reduce((a,v)=>a+(+v.amt||0),0);e.innerHTML=`<div class="top"><div><div class="eyebrow">Customer portal</div><h1>Welcome,${esc(p.name)}</h1></div><div class="topright"><button class="btn" onclick="signOutCustomer()">Sign Out</button></div></div><div class="grid three"><div class="card"><div class="kpi-label">Service property</div><div class="kpi" style="font-size:18px">${esc(p.street)}</div><div class="small">${(+p.sqft||0).toLocaleString()} ft² mapped mow area</div></div><div class="card"><div class="kpi-label">Next expected service</div><div class="kpi" style="font-size:22px">${next?dt(next):'To schedule'}</div><div class="small">Scheduled by your lawn company</div></div><div class="card"><div class="kpi-label">Open balance</div><div class="kpi">$${open.toFixed(2)}</div><div class="small">${p.inv.filter(v=>invoiceAmountDue(v)>0).length} unpaid invoice${p.inv.filter(v=>invoiceAmountDue(v)>0).length===1?'':'s'}</div></div></div><div class="grid two"><div class="card"><h2>Contact & Billing</h2><div class="sl"><span>Email</span><strong>${esc(p.email)}</strong></div><div class="sl"><span>Phone</span><strong>${esc(p.phone||'—')}</strong></div><div class="sl"><span>Billing address</span><strong>${esc(p.billingAddress||p.street)}</strong></div><div class="sl"><span>Invoice delivery</span><strong>${esc(p.invoicePreference||'Email')}</strong></div><div class="actions"><button class="btn" onclick="editCustomerProfile()">Edit Information</button></div></div><div class="card"><h2>Service Information</h2><div class="sl"><span>Estimated mow price</span><strong>$${priceFor(p)} / visit</strong></div><div class="sl"><span>Last service</span><strong>${p.visits[0]?dt(p.visits[0].date):'Not serviced yet'}</strong></div><div class="sl"><span>Account ID</span><strong>${esc(p.customerPortalId||'—')}</strong></div><p class="small">${esc(p.serviceNotes||'No special access or service notes on file.')}</p><div class="actions"><button class="btn primary" onclick="go('portal')">Invoices & Messages</button></div></div></div>`}
function editCustomerProfile(){const p=customerRecord();if(!p)return;openM(`<h2>Edit Customer Information</h2><div class="form"><label>Name<input id="ep_n" value="${esc(p.name)}"></label><label>Email<input id="ep_e" type="email" value="${esc(p.email)}"></label><label>Phone<input id="ep_p" type="tel" value="${esc(p.phone||'')}"></label><label>Billing Address<input id="ep_b" value="${esc(p.billingAddress||p.street)}"></label><label>Service Notes<textarea id="ep_s" rows="3">${esc(p.serviceNotes||'')}</textarea></label></div><div class="actions"><button class="btn" onclick="closeM()">Cancel</button><button class="btn primary" onclick="saveCustomerProfile()">Save</button></div>`)}
async function saveCustomerProfile(){const p=customerRecord();if(!p)return;const patch={name:$('ep_n').value.trim()||p.name,email:$('ep_e').value.trim()||p.email,phone:$('ep_p').value.trim(),billingAddress:$('ep_b').value.trim()||p.street,serviceNotes:$('ep_s').value.trim()};try{const d=await customerRequest('/api/customer/profile',{method:'PATCH',body:JSON.stringify(patch)});CUSTOMER_ACCOUNT=normalizeCustomerAccount(d.customer);closeM();render();toast('Customer information updated')}catch(e){toast(e.message)}}
function renderPro(){const p=cur(),vs=p.visits,ov=avg(vs,'ov'),cov=avg(vs,'cov'),ot=vs.length?Math.round(vs.filter(v=>v.time<=eta(p)*1.15).length/vs.length*100):0,eff=Math.round(100-ov),ms=mowerSetting(),last=vs[0],rate=proofRate(p),revHour=Math.round(priceFor(p)/Math.max(1,eta(p))*60),insights=[];if(!activeMower())insights.push(['Add mower profile','Enter the mower height range or real numbered positions so crew instructions match the deck.','uxOpenSettings(\'equipment\')']);else if(!ms.ok)insights.push(['Check mower range',ms.note,'mowerForm(\''+activeMower().id+'\')']);if(last?.pattern===rec(p))insights.push(['Rotate pattern','The recommended pattern matches the last recorded cut; review history before dispatch.','go(\'history\')']);if(rate<80)insights.push(['Improve completion proof',`${vs.length?rate+'%':'No Records'} of the last 10 services include a photo. Require a photo at job completion for stronger invoice proof.`,'go(\'settings\')']);if(dsl(p)!=null&&dsl(p)>8)insights.push(['Service is late',`${dsl(p)} days since the last recorded cut. Check the weekly route.`,'go(\'route\')']);if(!insights.length)insights.push(['Property looks ready','Mower setup, proof-photo compliance, and service timing are within the current rules.','go(\'dashboard\')']);$('procare').innerHTML=`<div class="top"><div><div class="eyebrow">TurfOS Intelligence Engine</div><h1>Property Decision Center</h1></div><div class="topright">${propSelect()}<button class="btn primary" onclick="report()">Export Property Report</button></div></div><div class="grid kpis"><div class="card"><div class="kpi-label">Cut target</div><div class="kpi">${esc(S.set.h||'3.5"')}</div><div class="small">Recommended grass height</div></div><div class="card"><div class="kpi-label">Mower setting</div><div class="kpi" style="font-size:22px">${esc(ms.label)}</div><div class="small">${esc(activeMower()?.name||'No mower profile')}</div></div><div class="card"><div class="kpi-label">Pattern now</div><div class="kpi" style="font-size:20px">${patternIcon(rec(p))} ${esc(rec(p))}</div><div class="small">Previous: ${last?esc(last.pattern):'—'}</div></div><div class="card"><div class="kpi-label">Proof photos</div><div class="kpi">${vs.length?rate+'%':'No Records'}</div><div class="small">Last 10 completed services</div></div><div class="card"><div class="kpi-label">Estimated Revenue / Crew Hour</div><div class="kpi">${eta(p)>0?'$'+revHour:'—'}</div><div class="small">Price ÷ estimated mow time</div></div></div><div class="grid two"><div class="card"><div class="st"><h2>Recommended Actions</h2><span class="small">Rule-based property checks</span></div><div class="intel-grid">${insights.map(x=>`<div class="intel-action"><strong>${esc(x[0])}</strong><div class="small">${esc(x[1])}</div><button class="btn sm" style="margin-top:8px" onclick="${x[2]}">Open</button></div>`).join('')}</div></div><div class="card ux-equipment-card"><div class="st"><h2>Mowers & Deck Settings</h2><button class="btn sm primary" onclick="mowerForm()">＋ Add Mower</button></div>${(S.set.mowers||[]).length?(S.set.mowers||[]).map(m=>`<div class="sl"><span><strong>${esc(m.name)}</strong><br><span class="small">${esc(m.makeModel||'Custom profile')} · ${m.min}\"–${m.max}\" · ${m.step}\" steps</span></span><span><button class="btn sm" onclick="setActiveMower('${m.id}')">${String(S.set.activeMowerId)===String(m.id)?'Active':'Use'}</button> <button class="btn sm" onclick="mowerForm('${m.id}')">Edit</button> <button class="btn sm" onclick="deleteMower('${m.id}')">×</button></span></div>`).join(''):'<div class="small">No mower profiles yet. Add the actual mower height range or numbered-position map to translate turf targets into real deck settings.</div>'}</div></div><div class="grid two" style="margin-top:16px"><div class="card"><div class="st"><h2>Operational Quality</h2></div>${[['Proof-photo compliance',rate]].map(m=>`<div class="metric"><div class="mh"><span>${m[0]}</span><strong>${vs.length?(+m[1]||0).toFixed(1)+'%':'No Records'}</strong></div><div class="progress"><div class="bar" style="width:${Math.max(0,Math.min(100,+m[1]||0))}%"></div></div></div>`).join('')}</div><div class="card"><div class="st"><h2>What TurfOS Is Using</h2></div><div class="sl"><span>Property area</span><strong>${(+p.sqft||0).toLocaleString()} ft²</strong></div><div class="sl"><span>Estimated Service Time</span><strong>~${eta(p)} min</strong></div><div class="sl"><span>Pattern history</span><strong>${vs.length} services</strong></div><div class="sl"><span>Grass target</span><strong>${esc(S.set.h||'3.5"')}</strong></div><div class="sl"><span>Active mower</span><strong>${esc(activeMower()?.name||'Not set')}</strong></div><div class="sl"><span>Weather scheduling</span><strong>Rain ≥ ${S.set.weatherRainProb}% / ${S.set.weatherRainIn}\"</strong></div></div></div>`}
function renderAn(){const visits=S.p.flatMap(p=>p.visits||[]),durations=visits.filter(v=>Number.isFinite(Number(v.time))&&Number(v.time)>0),invoices=S.p.flatMap(p=>p.inv||[]),paid=invoices.reduce((n,v)=>n+invoiceAmountReceived(v),0),outstanding=invoices.reduce((n,v)=>n+invoiceAmountDue(v),0),money=n=>'$'+n.toFixed(2);$('analytics').innerHTML=`<div class="top"><div><div class="eyebrow">Business Records</div><h1>Analytics</h1><p class="small">Based on saved mowing records and invoice statuses. Estimates are labeled separately.</p></div></div><div class="grid billing-kpis">${[['Recorded Mows',visits.length],['Average Recorded Duration',durations.length?Math.round(durations.reduce((n,v)=>n+Number(v.time),0)/durations.length)+' min':'No Records'],['Invoices Marked Paid',money(paid)],['Outstanding Invoices',money(outstanding)]].map(([label,value])=>`<div class="card"><div class="kpi-label">${label}</div><div class="kpi">${value}</div></div>`).join('')}</div><section class="card" style="margin-top:20px"><div class="st"><h2>Records by Property</h2></div><div class="billing-table-scroll"><table><thead><tr><th>Property</th><th>Recorded Mows</th><th>Average Duration</th><th>Completion Photos</th><th>Recorded Invoice Total</th></tr></thead><tbody>${S.p.map(p=>{const valid=p.visits.filter(v=>Number(v.time)>0);return `<tr><td>${esc(p.name)}</td><td>${p.visits.length}</td><td>${valid.length?Math.round(valid.reduce((n,v)=>n+Number(v.time),0)/valid.length)+' min':'—'}</td><td>${p.visits.filter(v=>v.proofPhoto).length} / ${p.visits.length}</td><td>${money(p.inv.reduce((n,v)=>n+(Number(v.amt)||0),0))}</td></tr>`}).join('')}</tbody></table></div></section>`}
function mergeAnalytics(){const source=$('procare'),target=$('analytics');uxEquipmentCard=source?.querySelector('.ux-equipment-card')||null;if(uxEquipmentCard)uxEquipmentCard.remove();if(!source||!target||!source.firstElementChild)return;const section=document.createElement('section');section.className='analytics-property-insights';const title=source.querySelector('h1');if(title){const heading=document.createElement('h2');heading.textContent='Property Insights';title.replaceWith(heading)}const eyebrow=source.querySelector('.eyebrow');if(eyebrow)eyebrow.textContent='Property performance';while(source.firstChild)section.append(source.firstChild);target.append(section)}
function renderSet(){uxCaptureSettingsDraft();const s=S.set;$('settings').innerHTML=`<div class="top"><div><div class="eyebrow">Configuration</div><h1>Settings</h1><p class="small">Set your company defaults, manage your team, and choose how completed jobs are handled.</p></div></div>${['biz','crew'].includes(S.mode)?accountCard():''}${isOwner()?onboardingCardHTML():''}<div class="card" style="margin-bottom:16px"><div class="st"><h2>Field App & Cloud Sync</h2></div><div class="small">Install TurfOS on a phone for a full-screen field app. Signed-in owner and crew accounts use the same cloud workspace. The device keeps a local copy for startup when signal is weak.</div><div class="actions"><button class="btn" onclick="installTurfOS()">Install TurfOS App</button><button class="btn" onclick="syncNow()">Sync Now</button></div></div><div class="grid two settings-grid"><div class="card"><h2>Mowing Preferences</h2><p class="small">Default instructions for your team. Individual properties can have their own settings.</p><div class="form">
<label>Default Cut Height<input id="s_h" value='${s.h}'></label><div class="small">The default grass height shown in yard plans.</div><label>Minimum Rain-Free Window (Hours)<input id="s_rain" type="number" value="${s.rain}"></label>
<div class="small">How many dry hours to look for when reviewing weather conditions.</div><label>Pattern Rotation Window<select id="s_rot">${[2,3,4].map(n=>`<option value="${n}"${n==s.rot?' selected':''}>Last ${n} cuts</option>`).join('')}</select></label>
<div class="small">Avoid repeating the mowing directions used in this many recent cuts.</div><label><input id="s_require_photo" type="checkbox" ${s.requireProofPhoto!==false?'checked':''}> Require a completion photo when finishing a mow</label></div></div><div class="card"><h2>Mowing Prices</h2><p class="small">Calculate a starting price from the mapped lawn area. You can override the price for each property.</p><div class="form">
<div class="settings-rate-pair"><label>Mowing Rate ($)<input id="s_mowing_rate" type="number" min="0.01" step="0.01" placeholder="e.g. 5.00" value="${s.mowingRate||''}"></label><label>Per Lawn Area (ft²)<input id="s_mowing_rate_area" type="number" min="1" step="1" value="${s.mowingRateArea||1000}"></label></div><div class="small">Example: $5 per 1,000 ft² gives a $50 mowing estimate for 10,000 ft². Use your own rate. Owner prices override the calculation.</div><label><input id="s_auto_price" type="checkbox" ${s.autoPrice!==false?'checked':''}> Calculate mowing prices automatically</label></div></div><div class="card"><h2>Mowing Time Estimates</h2><p class="small">Used in customer details, yard plans, and the service calendar.</p><div class="form"><div class="settings-rate-pair"><label>Minutes to Mow<input id="s_mowing_time_minutes" type="number" min="0.1" step="0.1" value="${s.mowingTimeMinutes||2}"></label><label>Per Lawn Area (ft²)<input id="s_mowing_time_area" type="number" min="1" step="1" value="${s.mowingTimeArea||1000}"></label></div><div class="small">All automatic mowing-time estimates use this rate, plus 5 minutes of setup per property. Owner-set property times take priority. Save changes using Save Settings below.</div></div></div><div class="card settings-advanced"><h2>Advanced Mapping</h2><p class="small">Optional map data connections. Leave these blank to use the built-in sources.</p><details><summary>Show Map Data Connections</summary><div class="form"><label>Parcel Layer URL Override (ArcGIS FeatureServer or MapServer Layer)<input id="s_parcel" type="url" placeholder="Automatic: Summit County, Ohio" value="${esc(s.parcelUrl)}"></label><label>Additional Roof Footprints Layer (ArcGIS Polygon Layer, Optional)<input id="s_roof" type="url" placeholder="County or LiDAR-derived building footprints" value="${esc(s.roofLayer)}"></label><div class="small">Summit County public parcel and building layers are built in. For tree-covered sites, a county or LiDAR-derived building-footprint polygon layer can supplement the aerial view. Raw LiDAR point clouds must first be classified and converted to polygons by a GIS provider. Layers need browser access and CORS.</div></div></details></div>
${paymentSettingsHTML()}<div class="card"><h2>Billing & Invoice Delivery</h2><label class="setup-check"><input id="s_service_reminders" type="checkbox" ${s.serviceReminders!==false?'checked':''}> Email customers the day before scheduled lawn service</label><p class="small">Reminders send daily at 11 AM Eastern during daylight saving time and 10 AM in winter, using saved calendar visits. A valid customer email and the server reminder service are required.</p><p class="small">Choose how invoices are sent and where customers can reply.</p><div class="form"><label><input id="s_auto_invoice" type="checkbox" ${s.autoInvoice!==false?'checked':''}> Automatically bill completed work</label><label>When Should Customers Be Billed?<select id="s_billing_frequency"><option value="service" ${!s.billingFrequency||s.billingFrequency==='service'?'selected':''}>After each service</option><option value="weekly" ${s.billingFrequency==='weekly'?'selected':''}>Weekly</option><option value="biweekly" ${s.billingFrequency==='biweekly'?'selected':''}>Every two weeks</option><option value="monthly" ${s.billingFrequency==='monthly'?'selected':''}>Monthly</option></select></label><label>First Billing Date<input id="s_billing_anchor" type="date" value="${esc(s.billingAnchor||dateAdd(today(),7))}"></label><p class="small">Weekly and every-two-week billing repeat from this date. Monthly repeats on the same day (or the last day of a shorter month). Each property gets one invoice for its completed services. Work completed on a billing date may be included in the next run. Existing invoices stay unchanged. Scheduled delivery requires the billing automation to be deployed.</p><label>Business Name<input id="s_business" value="${esc(BIZ_ACCOUNT?.companyName||s.businessName||'TurfOS Lawn Care')}" ${BIZ_ACCOUNT?'readonly':''}></label><label>Business Email / Customer Reply-To<input id="s_business_email" type="email" placeholder="turfos.business@gmail.com" value="${esc(s.businessEmail||'')}"></label><details class="settings-invoice-advanced"><summary>Advanced Delivery Connections</summary><div class="form"><label>Automatic Invoice Email Endpoint<input id="s_email_endpoint" value="${esc(s.invoiceEmailEndpoint||'/api/send-invoice')}" placeholder="/api/send-invoice"></label><label>Invoice Delivery Webhook (Optional Fallback)<input id="s_webhook" type="url" placeholder="https://hook.us1.make.com/..." value="${esc(s.invoiceWebhook)}"></label><label>Customer Intake Webhook (Optional)<input id="s_customer_webhook" type="url" placeholder="https://..." value="${esc(s.customerWebhook||'')}"></label><input id="s_payment" type="hidden" value="${esc(s.paymentLink)}"><div class="small">TurfOS now includes a secure server email function at <strong>/api/send-invoice</strong>. Add your business email here, then configure the included Resend/Cloudflare settings once. Your API key stays on the server, never in the browser.</div><div class="actions"><button class="btn" type="button" onclick="testInvoiceEmailSetup()">Test Email Setup</button></div><div id="email_test_status" class="small"></div></div></details></div></div></div><div class="card settings-save-bar"><div class="settings-save-hint"><strong>Company Settings</strong><span class="small">Save changes before leaving. Crew changes save immediately.</span></div><div class="actions"><button class="btn" onclick="exportData()">⬇ Backup Data</button><button class="btn" onclick="$('imp').click()">⬆ Restore Backup</button><button class="btn primary" onclick="saveSet()">Save Settings</button></div></div>`;if(isOwner()){loadPaymentSettings()};uxSettings()}
function invoiceEndpoint(raw){const v=(raw||'/api/send-invoice').trim();if(/^https:\/\//i.test(v))return v;if(location.protocol==='http:'||location.protocol==='https:')return new URL(v||'/api/send-invoice',location.origin).href;throw new Error('TurfOS must be opened from the hosted https:// website to send invoices. Email cannot work from a downloaded file.');}
async function emailServerHealth(raw){const endpoint=invoiceEndpoint(raw),u=new URL('/api/email-health',new URL(endpoint).origin);const r=await fetchT(u.href,{headers:{Accept:'application/json'}},10000),d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||('Email server health check returned HTTP '+r.status));return d;}
async function testInvoiceEmailSetup(){const e=$('email_test_status'),raw=($('s_email_endpoint')?.value||S.set.invoiceEmailEndpoint||'/api/send-invoice').trim(),email=($('s_business_email')?.value||S.set.businessEmail||'').trim();if(!email){if(e)e.textContent='Enter your business email first.';return}if(e)e.textContent='Checking email server…';try{const health=await emailServerHealth(raw);if(!health.worker)throw new Error('The TurfOS email worker is not active on this site. Re-upload the full TurfOS ZIP/folder with _worker.js at the root.');if(!health.apiKey)throw new Error('Email worker is online, but RESEND_API_KEY is missing in Cloudflare Variables and Secrets.');if(e)e.textContent='Server online. Sending test email…';const endpoint=invoiceEndpoint(raw),payload={event:'invoice.test',customer:{name:'TurfOS Test',email,address:'Test property'},invoice:{id:'TEST-'+Date.now().toString().slice(-6),date:today(),description:'TurfOS email setup test',amount:0},business:{name:($('s_business')?.value||S.set.businessName||'TurfOS Lawn Care'),email},paymentLink:'',message:'TurfOS invoice email delivery test'};const r=await fetchT(endpoint,{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+authToken()},body:JSON.stringify(payload)},30000);const data=await r.json().catch(()=>({}));if(!r.ok)throw new Error(data.error||('HTTP '+r.status));if(e)e.textContent='✓ Email server works. Test email sent to '+email;toast('Email setup works')}catch(err){let m=err?.message||'Email test failed';if(/failed to fetch/i.test(m))m='Cannot reach the TurfOS email worker. Make sure you are on the hosted https:// site and that _worker.js was included in the Cloudflare deployment.';if(e)e.textContent='✕ '+m;toast('Email setup failed: '+m)}}
function saveMowingRate(){if(!isOwner())return toast('Only the owner can change pricing');const rate=Number($('s_mowing_rate').value),area=Number($('s_mowing_rate_area').value);if(!Number.isFinite(rate)||rate<=0)return toast('Enter a mowing rate greater than zero');if(!Number.isFinite(area)||area<1)return toast('Enter a lawn area of at least 1 ft²');S.set.mowingRate=rate;S.set.mowingRateArea=area;S.set.autoPrice=$('s_auto_price').checked;save();const status=$('mowing_rate_status');if(status)status.textContent='Saved · $'+rate.toFixed(2)+' per '+area.toLocaleString()+' ft²';toast('Mowing rate saved')}
function saveSet(){if(!isOwner())return toast('Only the owner can change company settings');let paymentSettings;try{paymentSettings=paymentSettingsValues();invoicePricing(35,paymentSettings)}catch(e){return toast(e.message)}const parcelUrl=$('s_parcel').value.trim().replace(/\/+$/,''),roofLayer=$('s_roof').value.trim().replace(/\/+$/,''),webhook=$('s_webhook').value.trim(),customerWebhook=$('s_customer_webhook').value.trim(),payment=$('s_payment').value.trim(),businessEmail=$('s_business_email').value.trim(),emailEndpoint=$('s_email_endpoint').value.trim()||'/api/send-invoice',valid=u=>!u||/^https:\/\/[^\s/?#]+\/.*\/(FeatureServer|MapServer)\/\d+$/i.test(u),validHttp=u=>!u||/^https:\/\//i.test(u);if(businessEmail&&!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(businessEmail))return toast('Enter a valid business email');if(!/^\/|^https:\/\//i.test(emailEndpoint))return toast('Email endpoint must be /api/... or an HTTPS URL');if(!valid(parcelUrl)||!valid(roofLayer))return toast('Use HTTPS ArcGIS layer URLs ending in /FeatureServer/0 or /MapServer/0');if(!validHttp(webhook)||!validHttp(customerWebhook)||!validHttp(payment))return toast('Webhook and payment links must use HTTPS');const mowingRateRaw=$('s_mowing_rate').value.trim(),mowingRate=Number(mowingRateRaw),mowingRateArea=Number($('s_mowing_rate_area').value);if(mowingRateRaw&&(!Number.isFinite(mowingRate)||mowingRate<=0))return toast('Enter a mowing rate greater than zero');if(!Number.isFinite(mowingRateArea)||mowingRateArea<1)return toast('Enter a lawn area of at least 1 ft²');const mowingTimeMinutes=Number($('s_mowing_time_minutes').value),mowingTimeArea=Number($('s_mowing_time_area').value);if(!Number.isFinite(mowingTimeMinutes)||mowingTimeMinutes<=0||!Number.isFinite(mowingTimeArea)||mowingTimeArea<1)return toast('Enter a positive mowing time and lawn area');const billingFrequency=$('s_billing_frequency').value,billingAnchor=$('s_billing_anchor').value;if(!['service','weekly','biweekly','monthly'].includes(billingFrequency)||billingFrequency!=='service'&&!TurfBilling.valid(billingAnchor))return toast('Choose a valid billing date');const roofChanged=roofLayer!==S.set.roofLayer;if(roofChanged)S.bp.forEach(p=>{p.buildingDataVersion=0;p.houseMissing=true;p.roofConfirmed=false});S.set={...S.set,...paymentSettings,billingFrequency,billingAnchor,serviceReminders:$('s_service_reminders').checked,mowingRate:mowingRateRaw?mowingRate:null,mowingRateArea,mowingTimeMinutes,mowingTimeArea,h:$('s_h').value||'3.5"',rain:+$('s_rain').value||12,rot:+$('s_rot').value,autoPrice:$('s_auto_price').checked,autoInvoice:$('s_auto_invoice').checked,businessName:BIZ_ACCOUNT?.companyName||$('s_business').value.trim()||'TurfOS Lawn Care',businessEmail,invoiceEmailEndpoint:emailEndpoint,invoiceWebhook:webhook,customerWebhook,paymentLink:payment,requireProofPhoto:$('s_require_photo')?$('s_require_photo').checked:S.set.requireProofPhoto,weatherRainProb:$('s_weather_prob')?Math.min(100,Math.max(0,+$('s_weather_prob').value||60)):S.set.weatherRainProb,weatherRainIn:$('s_weather_in')?Math.max(0,+$('s_weather_in').value||.20):S.set.weatherRainIn,weatherWindMax:$('s_weather_wind')?Math.max(0,+$('s_weather_wind').value||28):S.set.weatherWindMax,parcelUrl,roofLayer};uxSettingsDirty=false;uxSettingsDraft=null;save();render();if(roofChanged&&S.mode==='biz'&&cur()?.parcel)findObstacles(cur());toast('Settings saved')}
function logForm(index=null,date=null){if(index!==null){const property=S.p[index];if(!property||(BIZ_ACCOUNT?.role==='crew'&&!visibleCrewMow(property,date||today())))return toast("This mow is not assigned to your crew");S.sel=index}const p=cur(),ms=mowerSetting();openM(`<h2>${index!==null?'Mark Mow Complete':'Log Mowing Service'}</h2><div class="form"><label>Property<select id="f_p" ${index!==null?'disabled':''}>${S.p.map((x,i)=>`<option value="${i}"${i==S.sel?' selected':''}>${x.name}</option>`).join('')}</select></label><label>Date<input id="f_d" type="date" value="${date||today()}"></label><label>Time of Mow<input id="f_clock" type="time" value="${String(new Date().getHours()).padStart(2,'0')}:${String(new Date().getMinutes()).padStart(2,'0')}" required></label><label>Pattern<select id="f_pat">${P.map(x=>`<option${x==rec(p)?' selected':''}>${x}</option>`).join('')}</select></label><label>Cut Height<input id="f_h" value='${S.set.h||'3.5"'}'></label><div class="small">Active mower: <strong>${esc(activeMower()?.name||'Not configured')}</strong> · Deck setting: <strong>${esc(ms.label)}</strong></div><label>Service Time (Minutes)<input id="f_t" type="number" value="${eta(p)}"></label><label>Weather<select id="f_w">${['Dry','Humid','Wet'].map(x=>`<option>${x}</option>`).join('')}</select></label><label>Service Notes (Optional)<textarea id="f_notes" placeholder="Anything the team or customer should know about this visit"></textarea></label>${crewSizeInput('f_crew')}${proofPhotoHTML('f_photo')}</div><div class="actions"><button class="btn" onclick="closeM()">Cancel</button><button class="btn primary" onclick="saveMow()">${index!==null?'Mark Complete':'Save Service + Proof'}</button></div>`)}
async function saveMow(){if(!validCrewSize('f_crew'))return toast('Enter the number of people working on this visit');const photo=await proofFromInput('f_photo');if(photoRequired(photo))return toast('Take a completion photo before saving the yard');if(!/^([01]\d|2[0-3]):[0-5]\d$/.test($('f_clock').value))return toast('Choose the time of the mow');const c=null,t=Math.max(1,+$('f_t').value||1),h=$('f_h').value;addVisit(+$('f_p').value,{date:$('f_d').value||today(),serviceTime:$('f_clock').value,crewSize:validCrewSize('f_crew'),pattern:$('f_pat').value,height:h,time:t,cov:c,ov:null,weather:$('f_w').value,proofPhoto:photo,notes:$('f_notes')?.value.trim()||'',mowerId:activeMower()?.id||'',mowerSetting:mowerSetting(parseFloat(h)||targetHeight()).label});closeM()}
function setAutoStatus(t){const e=$('autoSetupStatus');if(e)e.textContent=t}
function updatePropertyName(){const input=$('map_property_name'),p=cur(),name=input.value.trim();if(!name){input.value=p.name||'';return toast('Enter a property name')}p.name=name;p.propertyNameSet=true;input.value=name;save();$('property_name_save').textContent='Update Name';document.querySelectorAll('select[onchange="pick(this.value)"]').forEach(select=>{const option=select.options[S.sel];if(option)option.textContent=name+' · '+p.sqft.toLocaleString()+' ft²'});toast('Property name saved')}
async function autoSetupProperty(){const p=cur(),q=($('addr')?.value||p.addr||p.street||'').trim();if(!q)return toast('Enter the full service address first');setAutoStatus('Finding the address…');try{const r=await geo(q);if(!r)throw Error('Choose an address suggestion or enter the city and state');const changed=p.lat!==r.lat||p.lng!==r.lng;p.lat=r.lat;p.lng=r.lng;p.addr=r.address||q;p.street=r.address||q;p.geoSource=r.source;p.addressVerified=true;if(changed){p.parcel=null;p.parcelId='';p.obstacles=[];p.zones=[];p.sqft=0;p.visionCandidates=[];p.visionSummary=null;p.visionMessage='';delete p.mapReviewCompleteAt;delete p.drivewayReviewed;}p.autoLines=false;p.useParcelMow=false;save();render();setAutoStatus('Finding the property boundary…');await fillParcel(p);p.autoLines=false;p.useParcelMow=false;save();render();setAutoStatus('Address located. Choose Find grass with AI or Draw it myself to map the lawn. AI runs only when you press its button.');toast('Property located')}catch(e){obstacleLoading.delete(p);render();setAutoStatus(e.message||'Address lookup could not finish');toast('Check the property address')}}
