function customerSetupValidate(step){
 const existing=$('c_customer')?.value;
 if(step===0&&!existing){if(!$('c_n').value.trim())return ['c_n','Enter the customer name.'];const email=$('c_e').value.trim();if(email&&!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email))return ['c_e','Enter a valid email address.'];if(email&&S.customers.some(c=>c.email?.toLowerCase()===email.toLowerCase()))return ['c_e','This customer already exists. Use Add Property from their customer record.']}
 if(step===1){if(!$('c_property').value.trim())return ['c_property','Give this property a name.'];if(!$('c_s').value.trim())return ['c_s','Enter the service address.']}
 if(step===2){const raw=$('c_price').value.trim();if(raw&&(!Number.isFinite(Number(raw))||Number(raw)<0.5))return ['c_price','Enter a service amount of at least $0.50.']}
 if(step===3&&!/^\d{4}-\d{2}-\d{2}$/.test($('c_first_service').value))return ['c_first_service','Choose the first service date.'];return null;
}
function customerSetupNext(){
 if(customerSetupStep===0&&!$('c_s').value.trim()){const customer=S.customers.find(c=>c.id===$('c_customer')?.value);$('c_s').value=customer?.billingAddress||$('c_billing')?.value.trim()||''}
 const steps=customerSetupStep===4?[0,1,2,3]:[customerSetupStep];for(const step of steps){const error=customerSetupValidate(step);if(error){customerSetupStep=step;showCustomerSetupStep();$('customer_setup_error').textContent=error[1];$(error[0]).focus();return}}
 if(customerSetupStep===4)return saveCustomerSetupFinish();if(customerSetupStep===1&&!customerSetupPropertyId)return saveCustomerMappingDraft();customerSetupStep++;showCustomerSetupStep();
}
function customerSetupBack(){if(customerSetupStep===2&&customerSetupPropertyId){const index=S.p.findIndex(p=>String(p.id)===customerSetupPropertyId);if(index>=0){S.sel=index;closeM();go('map');setMapSetupStep(2)}return}customerSetupStep=Math.max(0,customerSetupStep-1);showCustomerSetupStep()}
function showCustomerSetupStep(){
 document.querySelectorAll('[data-setup-step]').forEach(el=>el.hidden=Number(el.dataset.setupStep)!==customerSetupStep);
 document.querySelectorAll('[data-setup-progress]').forEach(el=>{const step=Number(el.dataset.setupProgress),current=customerSetupStep>=2?customerSetupStep+1:customerSetupStep;el.classList.toggle('active',step===current);el.classList.toggle('complete',step<current);if(step===current)el.setAttribute('aria-current','step');else el.removeAttribute('aria-current')});
 $('customer_setup_back').hidden=customerSetupStep===0;$('customer_setup_count').textContent=`Step ${customerSetupStep>=2?customerSetupStep+2:customerSetupStep+1} of 6`;$('customer_setup_next').textContent=customerSetupStep===4?'Finish Setup →':customerSetupStep===1?'Continue to Mapping →':'Continue →';$('customer_setup_error').textContent='';
 if(customerSetupStep===4){const c=S.customers.find(c=>c.id===$('c_customer')?.value),raw=$('c_price').value.trim(),price=raw?invoicePricing(raw,{...S.set,paymentPricing:'include'}):null;const rows=[['Customer',c?.name||$('c_n').value],['Email',c?.email||$('c_e').value||'Not provided'],['Property',$('c_property').value],['Service address',$('c_s').value],['Service amount',price?'$'+Number(raw).toFixed(2):'Company pricing'],['Customer total',price?'$'+price.amt.toFixed(2)+' / visit':'Calculated from company pricing'],['First service',$('c_first_service').value],['Frequency',MOW_FREQUENCIES[$('c_frequency').value]],['Scheduling',$('c_auto_schedule').checked?'Automatic':'Manual']];$('customer_setup_review').innerHTML=rows.map(([label,value])=>`<div><span>${esc(label)}</span><strong>${esc(value)}</strong></div>`).join('')}
 $('mbox').scrollTop=0;if($('property-setup')?.classList.contains('active')){scrollTo(0,0);document.querySelector('main')?.scrollTo(0,0)}const heading=document.querySelector(`[data-setup-step="${customerSetupStep}"] h2`);if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true})}
}

function saveCust(){const priceRaw=$('c_price')?.value.trim()||'',customPrice=priceRaw?Number(priceRaw):null;if(priceRaw&&(!Number.isFinite(customPrice)||customPrice<0.5))return toast('Enter a service amount of at least $0.50');const selected=$('c_customer')?.value,ad=$('c_s').value.trim(),propertyName=$('c_property').value.trim();let c=S.customers.find(c=>c.id===selected);if(!propertyName||!ad)return toast('Enter the property name and service address');if(!c){const name=$('c_n').value.trim(),email=$('c_e').value.trim();if(!name)return toast('Enter the customer name');if(email&&!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email))return toast('Enter a valid email');if(email&&S.customers.some(c=>c.email?.toLowerCase()===email.toLowerCase()))return toast('This email belongs to an existing customer. Use Add Property and select that customer.');c={id:crypto.randomUUID(),name,email,phone:$('c_phone').value.trim(),billingAddress:$('c_billing').value.trim()};S.customers.push(c)}const p=sanitizeProperty({id:crypto.randomUUID(),customerId:c.id,customerName:c.name,name:propertyName,propertyNameSet:true,customPrice,paymentPricing:customPrice!==null?'include':undefined,email:c.email,phone:c.phone,billingAddress:c.billingAddress,addr:ad,street:ad,sqft:0,serviceNotes:$('c_notes').value.trim(),firstServiceDate:$('c_first_service').value||today(),frequencyAnchor:$('c_first_service').value||today(),mowingFrequency:$('c_frequency').value,autoSchedule:$('c_auto_schedule').checked,serviceDay:$('c_service_day').value==='auto'?null:Number($('c_service_day').value),zones:[],visits:[]});S.p.push(p);S.sel=S.p.length-1;save();closeM();render();openM(`<div class="customer-setup-wizard setup-saved"><span class="setup-kicker">Saved · Next up: mapping</span><h2>Let’s map ${esc(propertyName)}.</h2><p class="small">${esc(c.name)} and the property are saved. Next, confirm the location and outline the lawn. Then use the measured area to set pricing and scheduling.</p><div class="setup-map-steps"><span>1 · Find the property</span><span>2 · Outline the lawn</span><span>3 · Review & complete</span></div><div class="setup-footer"><button class="btn" onclick="skipPropertyMapping()">Continue Without Mapping</button><button class="btn primary" onclick="startSavedPropertyMapping()">Find My Property →</button></div></div>`)}
function report(){const p=cur(),vs=p.visits,t=`TURFOS PROPERTY REPORT\n${p.name} · ${p.street} · ${p.sqft} ft²\nGenerated ${today()}\n\nVisits: ${vs.length}\nAvg coverage: ${avg(vs,'cov').toFixed(1)}%\nAvg overlap: ${avg(vs,'ov').toFixed(1)}%\nAvg service time: ${Math.round(avg(vs,'time'))} min\nPattern rotation: ${rotPct(p)}%\nNext recommended pattern: ${rec(p)}\n\nDATE, PATTERN, HEIGHT, TIME, COVERAGE, OVERLAP, WEATHER\n`+vs.map(v=>[v.date,v.pattern,v.height,v.time+'m',v.cov+'%',v.ov+'%',v.weather].join(', ')).join('\n');
openM(`<h2>Property Report</h2><textarea id="rp" rows="14" style="width:100%;font-family:monospace;font-size:12px" readonly>${t}</textarea><div class="actions"><button class="btn" onclick="closeM()">Close</button><button class="btn primary" onclick="copyRep()">Copy Report</button></div>`)}
function copyRep(){const r=$('rp');r.select();try{navigator.clipboard.writeText(r.value).then(()=>toast('Report copied'),()=>{document.execCommand('copy');toast('Report copied')})}catch(e){try{document.execCommand('copy');toast('Report copied')}catch(x){toast('Press Ctrl/Cmd+C to copy')}}}
