async function authRequest(path,options={}){const headers={'Content-Type':'application/json',...(options.headers||{})},t=authToken();if(t)headers.Authorization='Bearer '+t;let r;try{r=await fetch(path,{...options,headers,cache:'no-store'})}catch(e){throw new Error('Cannot reach the TurfOS account server. Open the hosted https:// site and check the Cloudflare Worker.')};const raw=await r.text();let d={};try{d=raw?JSON.parse(raw):{}}catch(e){}if(!r.ok)throw new Error(d.error||('Account server returned '+r.status+(raw?' — '+raw.slice(0,180):'')));return d}
async function customerRequest(path,options={}){const headers={'Content-Type':'application/json',...(options.headers||{})},t=customerToken();if(t)headers.Authorization='Bearer '+t;let r;try{r=await fetch(path,{...options,headers,cache:'no-store'})}catch(e){throw new Error('Cannot reach the TurfOS customer server. Open the hosted https:// site and try again.')};const raw=await r.text();let d={};try{d=raw?JSON.parse(raw):{}}catch(e){}if(!r.ok)throw new Error(d.error||('Customer server returned '+r.status));return d}
function showCustomerAuth(tab='login'){const g=$('authgate');if(!g)return;g.classList.add('on');document.querySelector('.sidebar').style.visibility='hidden';document.querySelector('main').style.visibility='hidden';const qp=new URLSearchParams(location.search),linkedCode=String(qp.get('business')||qp.get('code')||'').trim().toUpperCase(),lastCode=linkedCode||localStorage.getItem('turfos-last-business-code')||'';$('authpanel').innerHTML=tab==='signup'?`<div class="eyebrow">Customer account</div><h1>Create Your Customer Account</h1><div class="small">${linkedCode?'Add your contact and service information below. Your signup is already connected to the correct lawn company.':'Enter the company code from your lawn provider, then add your contact and service information.'}</div><div class="tabs"><button class="btn" onclick="showCustomerAuth('login')">Log in</button><button class="btn primary">Sign Up</button></div><div id="autherr" class="autherr"></div><div class="form">${linkedCode?`<div id="linkedBusiness" class="authnote" style="margin:0 0 10px">Connecting to your lawn provider…</div>`:''}<label>Company Code *<input id="cu_code" value="${esc(lastCode)}" autocapitalize="characters" placeholder="TURF-ABC123" ${linkedCode?'readonly':''}></label><label>Your Name *<input id="cu_name" autocomplete="name" placeholder="Jordan Smith"></label><label>Email *<input id="cu_email" type="email" autocomplete="email" placeholder="you@example.com"></label><label>Phone<input id="cu_phone" type="tel" autocomplete="tel" placeholder="(330) 555-0123"></label><label>Service Address *<input id="cu_address" autocomplete="street-address" placeholder="123 Main St, Macedonia, OH 44056"></label><p class="small">We’ll use your service address for billing and property lookup.</p><details class="signup-billing"><summary>Use a Different Billing Address</summary><label>Billing Address<input id="cu_billing" autocomplete="billing street-address" placeholder="Enter only if different"></label></details><label>Service Notes<textarea id="cu_notes" rows="2" placeholder="Gate code, pets, areas to avoid, etc."></textarea></label><label>Password *<input id="cu_password" type="password" autocomplete="new-password" minlength="8" placeholder="At least 8 characters"></label></div><div class="actions"><button class="btn primary" onclick="customerSignup()">Create Customer Account</button><a class="btn" href="../index.html">Back</a></div>`:`<div class="eyebrow">Customer portal</div><h1>Welcome Back</h1><div class="small">Sign in with your email and password.</div><div class="tabs"><button class="btn primary">Log in</button><button class="btn" onclick="showCustomerAuth('signup')">Sign Up</button></div><div id="autherr" class="autherr"></div><div class="form"><label>Email<input id="cu_login_email" type="email" autocomplete="email" placeholder="you@example.com"></label><label>Password<input id="cu_login_password" type="password" autocomplete="current-password"></label></div><div class="actions"><button class="btn primary" onclick="customerLogin()">Log in as Customer</button><a class="btn" href="../index.html">Back</a></div><div class="authnote">New customer? Choose Sign Up.</div>`;if(tab!=='signup')$('authpanel').insertAdjacentHTML('beforeend',authPasswordResetLink('customer'));authArrangeAccessLinks();updateAuthBrandPreview(linkedCode?'':activeBrandName());if(linkedCode&&tab==='signup')loadLinkedBusiness(linkedCode)}
async function loadLinkedBusiness(code){try{const r=await fetch('/api/public/business?code='+encodeURIComponent(code),{cache:'no-store'}),d=await r.json();const el=$('linkedBusiness');if(!el)return;if(r.ok&&d.ok){el.innerHTML=`You are signing up with <strong>${esc(d.business.companyName)}</strong>${d.business.serviceArea?` · ${esc(d.business.serviceArea)}`:''}.`;S.set=S.set||{};S.set.businessName=d.business.companyName||S.set.businessName;updateAuthBrandPreview(d.business.companyName||'');document.title=`${d.business.companyName} · Customer Signup`}else{el.textContent='This customer link is not valid. Ask the lawn company for a new link.';updateAuthBrandPreview('')}}catch(e){const el=$('linkedBusiness');if(el)el.textContent='Could not verify the lawn company yet. Check your connection and try again.';updateAuthBrandPreview('')}}
async function customerSignup(){authError();const data={businessCode:$('cu_code').value.trim().toUpperCase(),name:$('cu_name').value.trim(),email:$('cu_email').value.trim(),phone:$('cu_phone').value.trim(),address:$('cu_address').value.trim(),billingAddress:$('cu_billing').value.trim()||$('cu_address').value.trim(),serviceNotes:$('cu_notes').value.trim(),password:$('cu_password').value};if(!data.businessCode||!data.name||!data.email||!data.address||!data.password)return authError('Company code, name, email, service address, and password are required.');try{const d=await customerRequest('/api/customer/signup',{method:'POST',body:JSON.stringify(data)});localStorage.setItem(CUSTOMER_TOKEN_KEY,d.token);localStorage.setItem('turfos-last-business-code',data.businessCode);CUSTOMER_ACCOUNT=normalizeCustomerAccount(d.customer);S.mode='cust';S.set.businessName=d.business?.name||'Your Lawn Company';S.set.businessEmail=d.business?.email||'';S.set.paymentLink=d.business?.paymentLink||'';hideBusinessAuth();buildNav();updateBusinessBrand();render();go('customer');toast('Customer account created')}catch(e){authError(e.message)}}
