async function loadCustomerSession(){const t=customerToken();if(!t){const qp=new URLSearchParams(location.search);showCustomerAuth(qp.get('signup')==='1'?'signup':'login');return false}try{const d=await customerRequest('/api/customer/me');CUSTOMER_ACCOUNT=normalizeCustomerAccount(d.customer);S.mode='cust';S.set.businessName=d.business?.name||'Your Lawn Company';S.set.businessEmail=d.business?.email||'';S.set.paymentLink=d.business?.paymentLink||'';hideBusinessAuth();return true}catch(e){localStorage.removeItem(CUSTOMER_TOKEN_KEY);CUSTOMER_ACCOUNT=null;showCustomerAuth('login');authError(e.message);return false}}
