function authError(msg=''){const e=$('autherr');if(!e)return;if(!msg){e.style.display='none';e.textContent='';return}e.textContent=msg;e.style.display='block'}
function showCrewAuth(tab=null){const qp=new URLSearchParams(location.search);tab=tab||(qp.get('signup')==='1'?'signup':'login');const code=String(qp.get('business')||qp.get('code')||'').trim().toUpperCase(),joining=tab==='signup',g=$('authgate');if(!g)return;g.classList.add('on');document.querySelector('.sidebar').style.visibility='hidden';document.querySelector('main').style.visibility='hidden';$('authpanel').innerHTML=`<div class="eyebrow">Field Worker Access</div><h1>${joining?'Join Your Company':'Sign in to Your Crew'}</h1><p class="small">${joining?'Create your own employee login using the code from your manager. Your manager will assign you to a crew.':'View assigned routes, property instructions, and record completed mows.'}</p><div class="tabs"><button class="btn ${joining?'':'primary'}" onclick="showCrewAuth('login')">Sign In</button><button class="btn ${joining?'primary':''}" onclick="showCrewAuth('signup')">Join Company</button></div><div id="autherr" class="autherr"></div><form onsubmit="event.preventDefault();${joining?'employeeSignup()':'businessLogin()'}"><div class="form">${joining?`<label>Company Code<input id="employee_code" value="${esc(code)}" autocapitalize="characters" required placeholder="Code from your manager"></label><label>Your Name<input id="employee_name" autocomplete="name" required></label><label>Phone (Optional)<input id="employee_phone" type="tel" autocomplete="tel"></label>`:''}<label>Email<input id="au_email" type="email" autocomplete="username" required></label><label>Password<input id="au_password" type="password" autocomplete="${joining?'new-password':'current-password'}" minlength="8" required></label></div><div class="actions"><a class="btn" href="../index.html">Back</a><button class="btn primary" type="submit">${joining?'Create Employee Account':'Employee Sign In'}</button></div></form><p class="small">${joining?'Already have an account? Sign in with your email and password.':'New employee? Choose Join Company.'}</p>`;if(tab!=='signup')$('authpanel').insertAdjacentHTML('beforeend',authPasswordResetLink('business'));authArrangeAccessLinks();updateAuthBrandPreview(activeBrandName())}
async function employeeSignup(){authError();const data={businessCode:$('employee_code').value.trim(),name:$('employee_name').value.trim(),phone:$('employee_phone').value.trim(),email:$('au_email').value.trim(),password:$('au_password').value};try{const d=await authRequest('/api/auth/crew/signup',{method:'POST',body:JSON.stringify(data)});localStorage.setItem(AUTH_TOKEN_KEY,d.token);await switchBusinessWorkspace(d.account);hideBusinessAuth();buildNav();render();go('crew');toast('Company joined. Your manager can now assign you to a crew.')}catch(e){authError(e.message)}}
