function showBusinessAuth(tab='login'){if(new URLSearchParams(location.search).get('entry')==='crew')return showCrewAuth();const g=$('authgate');if(!g)return;g.classList.add('on');document.querySelector('.sidebar').style.visibility='hidden';document.querySelector('main').style.visibility='hidden';$('authpanel').innerHTML=tab==='signup'?`<div class="eyebrow">Create business workspace</div><h1>Start Using TurfOS</h1><div class="small">Your company name will automatically brand the business dashboard, customer portal and invoices.</div><div class="tabs"><button class="btn" onclick="showBusinessAuth('login')">Sign in</button><button class="btn primary">Create Account</button></div><div id="autherr" class="autherr"></div><div class="form"><label>Company Name *<input id="au_company" autocomplete="organization" placeholder="Evergreen Lawn Care" oninput="updateAuthBrandPreview(this.value)"></label><label>Owner / Manager Name *<input id="au_owner" autocomplete="name" placeholder="Jordan Smith"></label><label>Business Email *<input id="au_email" type="email" autocomplete="email" placeholder="you@company.com"></label><label>Phone<input id="au_phone" type="tel" autocomplete="tel" placeholder="(330) 555-0123"></label><label>Primary Service Area<input id="au_area" placeholder="Macedonia / Summit County, OH"></label><label>Password *<input id="au_password" type="password" autocomplete="new-password" minlength="8" placeholder="At least 8 characters"></label></div><div class="actions"><button class="btn primary" onclick="businessSignup()">Create Business Account</button></div>`:`<div class="eyebrow">Business Account</div><h1>Welcome Back</h1><div class="small">Sign in to open your company's TurfOS workspace.</div><div class="tabs"><button class="btn primary">Sign in</button><button class="btn" onclick="showBusinessAuth('signup')">Create Account</button></div><div id="autherr" class="autherr"></div><div class="form"><label>Email<input id="au_email" type="email" autocomplete="email" placeholder="you@company.com"></label><label>Password<input id="au_password" type="password" autocomplete="current-password"></label></div><div class="actions"><button class="btn primary" onclick="businessLogin()">Sign in</button></div>`;if(tab!=='signup')$('authpanel').insertAdjacentHTML('beforeend',authPasswordResetLink('business'));authArrangeAccessLinks();updateAuthBrandPreview(tab==='signup'?'':activeBrandName())}
function hideBusinessAuth(){$('authgate')?.classList.remove('on');document.querySelector('.sidebar').style.visibility='';document.querySelector('main').style.visibility=''}
async function switchBusinessWorkspace(profile){BIZ_ACCOUNT=profile;const key='turfos-workspace-v1:'+businessId();let next=null;try{next=JSON.parse(localStorage.getItem(key))}catch(e){}const localCut=next?.activeCut;const cloud=await fetchCloudWorkspace();if(cloud){next=cloud;if(localCut)next.activeCut=localCut;}if(!next)next=freshBusinessWorkspace(profile);S=next;S.mode=profile.role==='crew'?'crew':'biz';fix();S.set.businessName=profile.companyName||S.set.businessName;if(profile.role!=='crew')S.set.businessEmail=profile.email||S.set.businessEmail;try{localStorage.setItem(key,JSON.stringify(S))}catch(e){}updateBusinessBrand();if(!cloud&&profile.role!=='crew')queueCloudSave();setSyncState(cloud?'ok':navigator.onLine?'saving':'offline')}
async function businessSignup(){authError();const data={companyName:$('au_company').value.trim(),ownerName:$('au_owner').value.trim(),email:$('au_email').value.trim(),phone:$('au_phone').value.trim(),serviceArea:$('au_area').value.trim(),password:$('au_password').value};if(!data.companyName||!data.ownerName||!data.email||!data.password)return authError('Company name, owner name, email and password are required.');try{const d=await authRequest('/api/auth/signup',{method:'POST',body:JSON.stringify(data)});localStorage.setItem(AUTH_TOKEN_KEY,d.token);await switchBusinessWorkspace(d.account);hideBusinessAuth();buildNav();render();go('dashboard');toast('Business Account created')}catch(e){authError(e.message)}}
async function businessLogin(){authError();const email=$('au_email').value.trim(),password=$('au_password').value;if(!email||!password)return authError('Enter your email and password.');try{const d=await authRequest('/api/auth/login',{method:'POST',body:JSON.stringify({email,password})});localStorage.setItem(AUTH_TOKEN_KEY,d.token);await switchBusinessWorkspace(d.account);hideBusinessAuth();buildNav();render();go(d.account.role==='crew'?'crew':'dashboard');toast('Signed in to '+bizName())}catch(e){authError(e.message)}}
