async function loadBusinessSession(){const t=authToken();if(!t){showBusinessAuth('login');return false}try{const d=await authRequest('/api/auth/me');await switchBusinessWorkspace(d.account);hideBusinessAuth();return true}catch(e){localStorage.removeItem(AUTH_TOKEN_KEY);showBusinessAuth('login');authError(e.message);return false}}
function customerSignupSectionHTML(){return BIZ_ACCOUNT&&isOwner()?`<div class="signup-link-field"><label for="customer-signup-url">Customer Signup Link</label><div class="signup-link-row"><input id="customer-signup-url" aria-label="Customer signup link" readonly value="${esc(customerSignupLink())}" onclick="this.select()"><button class="btn" type="button" onclick="copyCustomerSignupLink()">Copy Link</button></div></div><p class="small">Share this link or company code <strong>${esc(businessCode())}</strong>. Customers create their own login, then appear in your customer list.</p>`: ''}
function customerSignupLink(){const code=businessCode();return code?`${location.origin}/pages/customer.html?business=${encodeURIComponent(code)}&signup=1`:''}
async function copyCustomerSignupLink(){const link=customerSignupLink();if(!link)return toast('Business code is not available yet');try{await navigator.clipboard.writeText(link);toast('Customer Signup Link copied')}catch(e){openM(`<h2>Customer Signup Link</h2><input value="${esc(link)}" readonly onclick="this.select()"><div class="actions"><button class="btn primary" onclick="closeM()">Done</button></div>`)} }
