function accountCard(){if(!BIZ_ACCOUNT)return'';return`<div class="card"><div class="st"><h2>Business Account</h2>${B('Signed in')}</div><div class="sl"><span>Company</span><strong>${esc(BIZ_ACCOUNT.companyName)}</strong></div><div class="sl"><span>Owner / manager</span><strong>${esc(BIZ_ACCOUNT.ownerName)}</strong></div><div class="sl"><span>Email</span><strong>${esc(BIZ_ACCOUNT.email)}</strong></div><div class="sl"><span>Phone</span><strong>${esc(BIZ_ACCOUNT.phone||'—')}</strong></div><div class="sl"><span>Service area</span><strong>${esc(BIZ_ACCOUNT.serviceArea||'—')}</strong></div><div class="sl"><span>Company Code</span><strong>${esc(businessCode()||'—')}</strong></div>${customerSignupSectionHTML()}<div class="actions">${isOwner()?'<button class="btn" onclick="editBusinessAccount()">Edit Company Profile</button>':''}<button class="btn" onclick="businessLogout()">Sign Out</button></div></div>`}
