async function loadRoadPreview(map){const points=weekData().days[weekDay].route.order.filter(p=>coord(p)&&rsel?.[p.id]).map(p=>({lat:+p.lat,lng:+p.lng}));if(rst==='depot'&&coord(S.set.depot))points.unshift(S.set.depot);else if(rst==='me'&&rme)points.unshift({lat:rme[0],lng:rme[1]});if(points.length<2)return;const key=points.map(p=>p.lng+','+p.lat).join(';');const status=$('route_road_status');if(status)status.textContent='Loading Road Directions…';try{let geometry=roadPreviewCache.get(key);if(!geometry){const response=await fetchT('https://router.project-osrm.org/route/v1/driving/'+key+'?overview=full&geometries=geojson',{},12000);if(!response.ok)throw Error('Routing unavailable');const data=await response.json();if(data.code!=='Ok'||!data.routes?.[0]?.geometry?.coordinates?.length)throw Error('No road route');geometry=data.routes[0].geometry.coordinates.map(c=>[c[1],c[0]]);roadPreviewCache.set(key,geometry)}if(maps.rmap!==map)return;L.polyline(geometry,{color:'#2563eb',weight:5,opacity:.85}).addTo(map);map.fitBounds(geometry,{padding:[30,30],maxZoom:16});if(status)status.textContent='Road Directions'}catch(error){if(maps.rmap===map&&status)status.textContent='Road Directions Unavailable — Use Navigate';}}
