// Lightweight address suggestions shared by static and dynamically-rendered address forms.
const addressSuggestState=new WeakMap();
function isAddressField(input){if(!(input instanceof HTMLInputElement)||input.type==='hidden')return false;const key=(input.id+' '+input.name+' '+input.autocomplete+' '+input.placeholder+' '+(input.closest('label')?.innerText||'')).toLowerCase();return /^(addr|c_s|cu_addr|cu_address|cu_billing|cu_bill_addr|ep_b|depotaddr)$/.test(input.id.toLowerCase())||input.autocomplete==='street-address'||/address|street|start point|service location/.test(key)}
function addressDisplay(props){if(props.displayAddress)return props.displayAddress;const street=[props.housenumber,props.street||props.name].filter(Boolean).join(' ').trim(),city=props.city||props.town||props.village||props.hamlet||props.county,parts=[street,city,props.state,props.postcode].filter(Boolean);return [...new Set(parts)].join(', ')}
function addressMatchesQuery(item,query){const number=query.trim().match(/^(\d+[A-Za-z]?(?:[-/]\d+[A-Za-z]?)?)\s+/)?.[1];return !number||String(item.properties?.housenumber||'').trim().toLowerCase()===number.toLowerCase()}
function closeAddressSuggestions(input){const state=addressSuggestState.get(input);if(!state)return;clearTimeout(state.timer);state.controller?.abort();if(state.box)state.box.hidden=true;input.setAttribute('aria-expanded','false')}
function ensureAddressSuggestions(input){let state=addressSuggestState.get(input);if(state?.box?.isConnected)return state;let wrap=state?.wrap;if(!wrap?.isConnected){const parent=input.parentElement;if(!parent)return null;wrap=document.createElement('span');wrap.className='address-suggest-wrap';parent.insertBefore(wrap,input);wrap.append(input)}const box=document.createElement('div');box.className='address-suggest-list';box.setAttribute('role','listbox');box.hidden=true;wrap.append(box);state={...state,wrap,box,timer:null,controller:null,items:state?.items||[],active:-1};addressSuggestState.set(input,state);input.setAttribute('aria-autocomplete','list');input.setAttribute('aria-expanded','false');return state}
function chooseAddressSuggestion(input,index){const state=addressSuggestState.get(input),item=state?.items[index];if(!item||!addressMatchesQuery(item,input.value))return;const text=addressDisplay(item.properties||{}),coords=item.geometry?.coordinates;if(!text||!Array.isArray(coords))return;input.value=text;selectedAddressLookup.set(text.trim().toLowerCase(),{lat:+coords[1],lng:+coords[0],source:item.properties?.source||'Photon'});input.dispatchEvent(new Event('change',{bubbles:true}));const city=$('cu_bill_city'),region=$('cu_bill_state'),zip=$('cu_bill_zip');if(input.id==='cu_bill_addr'){if(city)city.value=item.properties.city||item.properties.town||item.properties.village||'';if(region)region.value=item.properties.state||'';if(zip)zip.value=item.properties.postcode||''}closeAddressSuggestions(input)}
function renderAddressSuggestions(input,items){const state=ensureAddressSuggestions(input);if(!state)return;items=items.filter(item=>addressMatchesQuery(item,input.value));state.items=items;state.active=-1;state.box.replaceChildren();if(!items.length){const empty=document.createElement('div');empty.className='address-suggest-message';empty.textContent=input.id==='addr'?'No exact suggestion for this address. Keep it entered and click Find Property to look up the lot.':'No matching house found yet. Add the city and state or ZIP to narrow the search.';state.box.append(empty)}else items.forEach((item,i)=>{const button=document.createElement('button');button.type='button';button.className='address-suggest-option';button.setAttribute('role','option');const text=addressDisplay(item.properties||{});button.textContent=text;button.addEventListener('pointerdown',event=>{event.preventDefault();chooseAddressSuggestion(input,i)});state.box.append(button)});const attribution=document.createElement('div');attribution.className='address-suggest-attribution';attribution.textContent='US address results: Esri / US Census · Photon / OpenStreetMap';state.box.append(attribution);state.box.hidden=false;input.setAttribute('aria-expanded','true')}
const countySuggestionCache=new Map();
const countySuggestionRequests=new Map();
const addressSuggestionCache=new Map();
async function countyAddressSuggestions(query,signal){
 const match=query.trim().match(/^(\d+[A-Za-z]?)(?:\s+(.*))?$/);if(!match)return [];
 const typed=(match[2]||'').split(',')[0].toUpperCase().replace(/[^A-Z0-9 ]/g,' ').trim();
 const url=new URL(SUMMIT_ADDRESSES+'/query');url.search=new URLSearchParams({f:'json',where:`ADDR_NUM = '${match[1].toUpperCase()}' AND COUNTY = 'SUM'`,outFields:'ADDR_NUM,PRE_DIR,STR_NAME,STR_TYPE,SUF_DIR,USPS_CITY,CITY,STATE,ZIP',returnGeometry:'true',outSR:'4326',resultRecordCount:'200'});
 const cacheKey=match[1].toUpperCase();let data=countySuggestionCache.get(cacheKey);if(!data){let pending=countySuggestionRequests.get(cacheKey);if(!pending){pending=(async()=>{const response=await fetch(url,{signal:AbortSignal.timeout(7000)});if(!response.ok)throw Error('County address suggestions unavailable');const result=await response.json();if(result.error)throw Error(result.error.message);if(countySuggestionCache.size>=100)countySuggestionCache.delete(countySuggestionCache.keys().next().value);countySuggestionCache.set(cacheKey,result);return result})();countySuggestionRequests.set(cacheKey,pending);pending.finally(()=>countySuggestionRequests.delete(cacheKey)).catch(()=>{})}data=await pending}

 const seen=new Set();return (data.features||[]).filter(f=>{const street=String(f.attributes?.STR_NAME||'').toUpperCase();return (!typed||typed.startsWith(street)||street.startsWith(typed))&&Number.isFinite(f.geometry?.x)&&Number.isFinite(f.geometry?.y)}).map(f=>{const a=f.attributes;return {properties:{housenumber:a.ADDR_NUM,street:[a.PRE_DIR,a.STR_NAME,a.STR_TYPE,a.SUF_DIR].filter(Boolean).join(' '),city:a.USPS_CITY||a.CITY,state:a.STATE,postcode:a.ZIP,source:'county GIS'},geometry:{coordinates:[f.geometry.x,f.geometry.y]}}}).filter(item=>{const key=addressDisplay(item.properties);if(seen.has(key))return false;seen.add(key);return true}).slice(0,6)
}
async function searchAddressSuggestions(input){const state=ensureAddressSuggestions(input);if(!state)return;const query=input.value.trim();state.controller?.abort();state.items=[];state.active=-1;if(query.length<3){closeAddressSuggestions(input);return}const controller=new AbortController();state.controller=controller;const timeout=setTimeout(()=>controller.abort(),12000);state.box.replaceChildren();const loading=document.createElement('div');loading.className='address-suggest-message';loading.textContent='Searching addresses…';state.box.append(loading);state.box.hidden=false;input.setAttribute('aria-expanded','true');try{const cacheKey=query.toLowerCase(),cached=addressSuggestionCache.get(cacheKey);if(cached){if(input.value.trim()===query&&!controller.signal.aborted)renderAddressSuggestions(input,cached);return}let items=[];const publish=found=>{items.push(...found.filter(item=>addressMatchesQuery(item,query)));const seen=new Set();items=items.filter(item=>{const key=addressDisplay(item.properties||{}).toLowerCase();if(seen.has(key))return false;seen.add(key);return true});if(items.length&&input.value.trim()===query&&!controller.signal.aborted)renderAddressSuggestions(input,items)};const results=await Promise.allSettled([nationwideAddressSuggestions(query,controller.signal).then(publish),fetch('https://photon.komoot.io/api/?'+new URLSearchParams({q:query,limit:'6',lang:'en'}),{signal:controller.signal}).then(async response=>{if(!response.ok)throw Error('Address suggestions unavailable');return (await response.json()).features||[]}).then(publish)]);if(controller.signal.aborted)return;if(results.every(r=>r.status==='rejected'))throw Error('Address suggestions unavailable');if(items.length){if(addressSuggestionCache.size>=100)addressSuggestionCache.delete(addressSuggestionCache.keys().next().value);addressSuggestionCache.set(cacheKey,items)}if(!items.length&&input.value.trim()===query)renderAddressSuggestions(input,items)}catch(error){if(error.name!=='AbortError'&&input.value.trim()===query){console.warn('Address suggestions unavailable',error);state.box.replaceChildren();const message=document.createElement('div');message.className='address-suggest-message';message.textContent='Address suggestions are unavailable right now. You can keep entering the address.';state.box.append(message);state.box.hidden=false;input.setAttribute('aria-expanded','true')}}finally{clearTimeout(timeout)}}
document.addEventListener('focusin',event=>{const input=event.target;if(!isAddressField(input))return;const state=ensureAddressSuggestions(input);if(state&&input.value.trim().length>=3){clearTimeout(state.timer);state.timer=setTimeout(()=>searchAddressSuggestions(input),180)}});
document.addEventListener('input',event=>{const input=event.target;if(!isAddressField(input))return;ensureAddressSuggestions(input);const state=addressSuggestState.get(input);closeAddressSuggestions(input);state.items=[];state.active=-1;const query=input.value.trim(),cached=addressSuggestionCache.get(query.toLowerCase());if(cached){renderAddressSuggestions(input,cached);return}state.timer=setTimeout(()=>searchAddressSuggestions(input),120)});

document.addEventListener('keydown',event=>{const input=event.target,state=addressSuggestState.get(input);if(!state||state.box.hidden)return;if((event.key==='ArrowDown'||event.key==='ArrowUp')&&state.items.length){event.preventDefault();event.stopImmediatePropagation();state.active=(state.active+(event.key==='ArrowDown'?1:-1)+state.items.length)%state.items.length;state.box.querySelectorAll('.address-suggest-option').forEach((option,i)=>option.classList.toggle('active',i===state.active))}else if(event.key==='Enter'&&state.items.length){event.preventDefault();event.stopImmediatePropagation();chooseAddressSuggestion(input,state.active>=0?state.active:0)}else if(event.key==='Escape'){event.stopImmediatePropagation();closeAddressSuggestions(input)}},true);
document.addEventListener('focusout',event=>{if(isAddressField(event.target)){const input=event.target;setTimeout(()=>{if(document.activeElement!==input)closeAddressSuggestions(input)},150)}});
