function invoicePricing(base,settings=S.set){
 const principal=Math.round(Number(base)*100),percent=Number(settings.paymentFeePercent??2.9),fixed=Math.round(Number(settings.paymentFeeFixed??0.30)*100);
 if(!Number.isSafeInteger(principal)||principal<0||!Number.isFinite(percent)||percent<0||percent>20||!Number.isSafeInteger(fixed)||fixed<0||fixed>1000)throw Error('Enter a valid amount and processing estimate.');
 const included=settings.paymentPricing==='include';
 const cents=included?Math.ceil((principal+fixed)/(1-percent/100)-1e-8):principal;
 const estimatedFee=Math.round(cents*percent/100)+fixed;
 return {amt:cents/100,pricing:{base:principal/100,mode:included?'include':'absorb',percent,fixed:fixed/100,estimatedFee:estimatedFee/100,estimatedNet:(cents-estimatedFee)/100}};
}
async function recordManualInvoice(id){const method=prompt('Payment method: cash or check','cash');if(!method)return;try{await authRequest('/api/payments/record-manual',{method:'POST',body:JSON.stringify({propertyId:String(cur().id),invoiceId:id,method:method.toLowerCase().trim()})});await pullCloudWorkspace(true);render();toast('Payment recorded')}catch(e){toast(e.message)}}
function invoiceAmountDue(v){return v.paid||['refunded','partially_refunded','disputed','dispute_lost'].includes(v.paymentStatus)?0:Number(v.amt)||0}
function invoiceAmountReceived(v){return v.paid?Math.max(0,(Number(v.amt)||0)-(Number(v.paymentRefunded)||0)):0}
function invoicePaymentBadge(v){const names={unpaid:'Unpaid',processing:'Processing',paid:'Paid',paid_manual:'Paid (cash / check)',failed:'Failed',refunded:'Refunded',partially_refunded:'Partially refunded',disputed:'Disputed',dispute_lost:'Dispute lost'};return B(names[v.paymentStatus]||(v.paid?'Paid':'Unpaid'),v.paid?'':'w')}
function invoicePaymentDetails(v){if(!v.paymentManaged)return '';if(v.paymentStatus==='paid_manual')return `<div class="small">Recorded ${esc(v.paymentMethod)} · ${esc(v.paymentRecordedAt?.slice(0,10)||'')}</div>`;return `<div class="small">${v.paymentFee==null?'Fees available after payment':`Processing fee: $${Number(v.paymentFee).toFixed(2)}<br>Net from original charge: $${Number(v.paymentNet).toFixed(2)}`}${v.paymentRefunded?`<br>Refunded: $${Number(v.paymentRefunded).toFixed(2)}`:''}</div>`}
function invoicePaymentAction(v){return v.paymentManaged?`<button class="btn sm" onclick="refreshInvoicePayment('${esc(v.id)}')">Refresh Payment</button>${['unpaid','failed'].includes(v.paymentStatus)?` <button class="btn sm" onclick="recordManualInvoice('${esc(v.id)}')">Record Cash / Check</button>`:''}`:`<button class="btn sm" onclick="togInv('${esc(v.id)}')">${v.paid?'Mark Unpaid':'Record cash / check'}</button>`}
