async function customerPayInvoice(id){try{const d=await customerRequest('/api/payments/customer-link',{method:'POST',body:JSON.stringify({invoiceId:id})});location.assign(d.url)}catch(e){toast(e.message)}}
function invoicePreview(){const el=$('invoice_price_preview');if(!el)return;try{const v=propertyInvoicePricing(cur(),$('iv_a').value);el.textContent=`Customer total: $${v.amt.toFixed(2)} · Estimated processing: $${v.pricing.estimatedFee.toFixed(2)} · Estimated net: $${v.pricing.estimatedNet.toFixed(2)}. Use the agreed customer price before sending.`}catch(e){el.textContent=e.message}}
function paymentSettingsHTML(){return `<div class="card payment-settings"><h2>Online Payments</h2><div id="stripe_connection_status" class="small">Checking payment setup…</div><div class="actions"><button class="btn primary" type="button" onclick="connectPayments(false)">Set Up / Continue Stripe</button><button class="btn" id="stripe_existing_button" type="button" onclick="connectPayments(true)" hidden>Connect Existing Stripe</button><button class="btn" type="button" onclick="loadPaymentSettings()">Refresh Status</button></div><p class="small">Customer payments go to your connected Stripe account. Bank payments are offered when Stripe enables ACH for your business.</p><div class="form"><label>Service Pricing<select id="s_payment_pricing" onchange="paymentSettingsPreview()"><option value="absorb" ${S.set.paymentPricing!=='include'?'selected':''}>Absorb processing costs</option><option value="include" ${S.set.paymentPricing==='include'?'selected':''}>Include estimated processing costs in service prices</option></select></label><div class="payment-fee-fields"><label>Estimated Processing Rate (%)<input id="s_payment_percent" type="number" min="0" max="20" step="0.01" value="${esc(S.set.paymentFeePercent??2.9)}" oninput="paymentSettingsPreview()"></label><label>Estimated fixed fee ($)<input id="s_payment_fixed" type="number" min="0" max="10" step="0.01" value="${esc(S.set.paymentFeeFixed??0.30)}" oninput="paymentSettingsPreview()"></label></div><p id="payment_settings_preview" class="small"></p><p class="small">One agreed service price applies to both card and bank payments. Estimates do not guarantee the net amount. Set rates for your Stripe pricing; other product fees may apply. Changes apply to new invoices. Existing invoices keep their price.</p></div></div>`}
function paymentSettingsValues(){return {paymentPricing:$('s_payment_pricing')?.value||'absorb',paymentFeePercent:Number($('s_payment_percent')?.value??2.9),paymentFeeFixed:Number($('s_payment_fixed')?.value??0.30)}}
function paymentSettingsPreview(){const el=$('payment_settings_preview');if(!el)return;try{const p=invoicePricing(35,paymentSettingsValues());el.textContent=`Example: $35 service amount → $${p.amt.toFixed(2)} customer price → approximately $${p.pricing.estimatedNet.toFixed(2)} after processing.`}catch(e){el.textContent=e.message}}
let paymentSettingsRequest=0;
async function loadPaymentSettings(){if(!isOwner()||!$('stripe_connection_status'))return;const request=++paymentSettingsRequest;paymentSettingsPreview();try{const d=await authRequest('/api/payments/status');if(request!==paymentSettingsRequest||!$('stripe_connection_status'))return;$('stripe_connection_status').textContent=!d.configured?'Online payments need administrator setup.':!d.connected?`Stripe is not connected (${d.mode} mode).`: `${d.mode==='test'?'TEST MODE · ':''}${d.chargesEnabled?'Ready to accept payments':'Setup incomplete'} · Bank payments: ${d.bankPaymentsEnabled?'enabled':'not enabled'} · Bank payouts: ${d.payoutsEnabled?'enabled':'setup needed'}${d.requirements?.length?' · Stripe needs additional account information.':''}`;$('stripe_existing_button').hidden=!d.existingAccountSupported||d.connected}catch(e){if(request===paymentSettingsRequest&&$('stripe_connection_status'))$('stripe_connection_status').textContent=e.message}}
async function connectPayments(existing){try{const d=await authRequest('/api/payments/connect',{method:'POST',body:JSON.stringify({existing})});location.assign(d.url)}catch(e){toast(e.message)}}
async function prepareInvoicePayment(p,v){
 if(v.paid)return '';
 clearTimeout(cloudSaveTimer);cloudSaveTimer=null;
 if(!await syncCloudWorkspace())throw Error('Invoice could not sync. Retry before sending a payment link.');
 const status=await authRequest('/api/payments/status');
 if(!status.connected){if(v.paymentManaged)throw Error('Reconnect Stripe before sending this invoice.');return ''}
 if(!status.chargesEnabled)throw Error('Complete Stripe setup before sending an online invoice.');
 const d=await authRequest('/api/payments/prepare',{method:'POST',body:JSON.stringify({propertyId:String(p.id),invoiceId:v.id})});
 v.paymentManaged=true;v.paymentStatus=v.paymentStatus||'unpaid';v.paymentUrl=d.url;
 return d.url;
}

function propertyPaymentSettings(p){return {...S.set,paymentPricing:p?.paymentPricing||S.set.paymentPricing||'absorb'}}
function propertyInvoicePricing(p,base=priceFor(p)){return invoicePricing(base,propertyPaymentSettings(p))}
function propertyPriceSummary(p){const v=propertyInvoicePricing(p);return `Service amount: $${Number(priceFor(p)).toFixed(2)} · Customer total: $${v.amt.toFixed(2)} · Estimated net: $${v.pricing.estimatedNet.toFixed(2)}`}
function newCustomerPricePreview(){const el=$('customer_price_preview');if(!el)return;const raw=$('c_price').value;if(!raw){el.textContent='Leave blank to use company pricing, or enter your service amount.';return}try{const v=invoicePricing(raw,{...S.set,paymentPricing:'include'});el.textContent=`Customer price: $${v.amt.toFixed(2)} per visit · Estimated net: $${v.pricing.estimatedNet.toFixed(2)}. This final price is used for new invoices and Stripe payments.`}catch(e){el.textContent=e.message}}
function billingPricePreview(){const el=$('billing_price_preview');if(!el)return;try{const p=cur(),base=$('bill_price').value||competitivePrice(p),v=invoicePricing(base,{...S.set,paymentPricing:$('bill_include_fees').checked?'include':'absorb'});el.textContent=`Customer total: $${v.amt.toFixed(2)} · Estimated net: $${v.pricing.estimatedNet.toFixed(2)}. Applies to new invoices.`}catch(e){el.textContent=e.message}}
function openPropertyBilling(index){if(!isOwner())return;const p=S.p[index];if(!p)return;closeM();S.sel=index;go('portal');billingPropertyId=String(p.id);renderPropertyBilling();$('portal').insertAdjacentHTML('afterbegin','<button class="btn sm" onclick="go(\'customers\')">← Customers</button>')}
function openCustomerBilling(index){if(!isOwner())return;const c=S.customers[index];if(!c)return;const properties=S.p.map((p,index)=>({p,index})).filter(({p})=>p.customerId===c.id);if(!properties.length)return toast('Add a property for this customer first');if(properties.length===1)return openPropertyBilling(properties[0].index);openM(`<h2>Manage Billing · ${esc(c.name)}</h2><p class="small">Choose a service property to manage its price and invoices.</p><form onsubmit="event.preventDefault();openPropertyBilling(Number(document.getElementById('customer_billing_property').value))"><div class="form"><label>Service Property<select id="customer_billing_property">${properties.map(({p,index})=>`<option value="${index}">${esc(p.name)} · ${esc(p.street||p.addr)}</option>`).join('')}</select></label></div><div class="actions"><button class="btn" type="button" onclick="closeM()">Cancel</button><button class="btn primary">Manage Billing</button></div></form>`)}

function setMapSetupStep(step){if(!Number.isInteger(step)||step<1||step>3)return;if(tr?.on)return toast('Finish or cancel your current outline first');const p=cur();if(step>1&&(!p.lat||!p.lng))return toast('Find the property location first');if(step>1&&p.parcelSelectionNeedsReview)return toast('Confirm the correct property lot first');mapSetupState={propertyId:String(p.id),step};renderMap();drawMap('emap',true);scrollTo(0,0);document.querySelector('main')?.scrollTo(0,0);requestAnimationFrame(()=>maps.emap?.invalidateSize())}

function saveCustomerMappingDraft(){saveCust();const p=cur();if(!p)return;p.setupPending=true;p.setupAutoSchedule=p.autoSchedule;p.setupAutoInvoice=p.autoInvoice;p.autoSchedule=false;p.autoInvoice=false;save();startSavedPropertyMapping()}
function resumeCustomerSetup(p){const index=S.customers.findIndex(c=>c.id===p.customerId);custForm('property',index);customerSetupPropertyId=String(p.id);$('c_property').value=p.name;$('c_s').value=p.street||p.addr||'';$('c_notes').value=p.serviceNotes||'';$('c_first_service').value=p.firstServiceDate||today();$('c_frequency').value=p.mowingFrequency||'weekly';$('c_service_day').value=p.serviceDay==null?'auto':String(p.serviceDay);$('c_auto_schedule').checked=p.setupPending?p.setupAutoSchedule!==false:p.autoSchedule!==false;const calculated=mappedMowingPrice(p);$('c_price').value=Number(p.customPrice)>0?p.customPrice:calculated??'';const summary=$('setup_mapped_price');summary.hidden=false;summary.textContent=`Mapped mow area: ${Number(plannedAreaSummary(p).mow||p.sqft||0).toLocaleString()} ft² · ${calculated===null?'Set a price or configure your area rate in Settings.':`Calculated service amount: $${Number(calculated).toFixed(2)} from your area rate.`}`;customerSetupStep=2;showCustomerSetupStep();newCustomerPricePreview()}
function saveCustomerSetupFinish(){if(!customerSetupPropertyId)return saveCust();const p=S.p.find(p=>String(p.id)===customerSetupPropertyId);if(!p)return toast('Property was not found. Reopen setup from Customers.');const raw=$('c_price').value.trim();p.customPrice=raw?Number(raw):null;p.useMappedPrice=!raw;p.paymentPricing=raw?'include':p.paymentPricing;p.firstServiceDate=$('c_first_service').value;p.frequencyAnchor=p.firstServiceDate;p.mowingFrequency=$('c_frequency').value;p.serviceDay=$('c_service_day').value==='auto'?null:Number($('c_service_day').value);p.autoSchedule=$('c_auto_schedule').checked;p.autoInvoice=p.setupAutoInvoice!==false;delete p.setupPending;delete p.setupAutoSchedule;delete p.setupAutoInvoice;save();closeM();render();go('customers');toast('Customer, map, price and schedule saved')}

function startSavedPropertyMapping(){closeM();go('map');if(cur()&&!cur().lat)void autoSetupProperty()}

function billingScheduleSummaryHTML(){const pending=S.bp.flatMap(p=>(p.visits||[]).filter(v=>v.billingPending&&!v.invoiceId).map(v=>({p,v})));const labels={service:'After Each Service',weekly:'Weekly',biweekly:'Every Two Weeks',monthly:'Monthly'},next=pending.map(x=>x.v.billingPending.date).sort()[0];return `<section class="card billing-schedule-summary"><div><span class="eyebrow">Customer billing</span><h2>${labels[S.set.billingFrequency]||labels.service}</h2><p class="small">${pending.length?pending.length+' completed services waiting · Next billing date '+esc(next):'Completed work follows your billing preference.'}</p></div><button class="btn" onclick="uxOpenSettings('billing')">Change Schedule</button></section>`}

function simplifyMapWorkspace(){
 const root=$('map');if(!root||S.mode!=='biz')return;
 root.querySelector('.ux-property-context')?.remove();
 const name=root.querySelector('.map-address-card form');if(name){const details=document.createElement('details');details.className='map-name-details';details.innerHTML='<summary>Rename This Property</summary>';name.before(details);details.append(name)}
 const card=root.querySelector('.property-map-card');if(!card)return;
 const canvas=document.createElement('div');canvas.className='map-canvas-workspace';const tools=document.createElement('aside');tools.className='map-tools-workspace';tools.setAttribute('aria-label','Lawn drawing tools');
 for(const child of [...card.children]){if(child.matches('.map-quick-edit,.advanced-map'))tools.append(child);else canvas.append(child)}
 card.append(canvas,tools);
 const heading=canvas.querySelector('.map-section-heading');if(heading)heading.remove();
 const metadata=canvas.querySelector('.st');if(metadata)metadata.classList.add('map-canvas-title');
 const legend=canvas.querySelector('.legend');if(legend){const details=document.createElement('details');details.className='map-legend-details';details.innerHTML='<summary>Map Colors & Guidance</summary>';legend.before(details);details.append(legend);for(const note of [...canvas.querySelectorAll(':scope > .small')])if(note.id!=='hint')details.append(note)}
 const maptools=canvas.querySelector('.maptools');if(maptools){const details=document.createElement('details');details.className='map-imagery-details';details.innerHTML='<summary>Satellite Imagery</summary>';canvas.append(details);details.append(maptools)}
 const completed=root.querySelector('.map-complete-card');if(completed){const extras=document.createElement('details');extras.className='map-review-extras';extras.innerHTML='<summary>Price, Time, Notes & Service Frequency</summary>';completed.append(extras);for(const child of [...completed.children])if(child.matches('.map-estimate-panel,.map-time-note')||child.classList.contains('property-notes'))extras.append(child)}
}

function navigationIcon(page){const paths={ai:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z"/>',dashboard:'<path d="M3 10 12 3l9 7v10H3Z"/><path d="M9 20v-7h6v7"/>',customers:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6M18 15a5 5 0 0 1 3 5"/>',route:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 11h18m-12 5h6"/>',portal:'<rect x="3" y="4" width="18" height="16" rx="3"/><path d="M3 10h18m-13 6h4"/>',team:'<circle cx="12" cy="7" r="3"/><path d="M6 21v-3a6 6 0 0 1 12 0v3M3 7a3 3 0 0 0 0 6m18-6a3 3 0 0 1 0 6"/>',history:'<path d="M3 11a9 9 0 1 1 2 7M3 4v7h7m2-4v6l4 2"/>',analytics:'<path d="M4 3v18h17M9 16v-5m5 5V7m5 9v-3"/>',settings:'<path d="m9 3-.6 3-2.8 1L3 6l-1 4 2.4 2-1 3 2.6 3 3-1 3 2 3-2 3 1 2.6-3-1-3L22 10l-1-4-2.6 1-2.8-1L15 3Z"/><circle cx="12" cy="11" r="3"/>',map:'<path d="m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2Zm6-2v16m6-14v16"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>'};return `<svg viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" focusable="false">${paths[page]||paths.dashboard}</svg>`}

function authPasswordResetLink(account){const query=new URLSearchParams({account}),code=new URLSearchParams(location.search).get('business');if(code)query.set('business',code);return `<a class="auth-reset-link" href="reset-password.html?${esc(query.toString())}">Reset Password</a>`}

function showCustomerBusinessChoice(businesses){let field=$('cu_login_business');if(!field){const label=document.createElement('label');label.textContent='Choose Your Lawn Company';field=document.createElement('select');field.id='cu_login_business';label.append(field);$('cu_login_password').closest('label').after(label)}field.innerHTML='<option value="">Choose a company</option>'+businesses.map(b=>`<option value="${esc(b.id)}">${esc(b.name)}</option>`).join('');authError('Your login matches more than one lawn company. Choose the company you want to open.')}

function authArrangeAccessLinks(){const panel=$('authpanel');if(!panel)return;panel.querySelectorAll('.actions a[href="../index.html"]').forEach(link=>link.remove());panel.insertAdjacentHTML('afterbegin','<a class="auth-back-arrow" href="../index.html" aria-label="Back to Account Selection" title="Back"><svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m14 6-6 6 6 6M8 12h12"/></svg></a>');const reset=panel.querySelector('.auth-reset-link'),password=panel.querySelector('input[autocomplete="current-password"]');if(reset&&password)password.closest('label').after(reset);panel.classList.toggle('login-panel',!!password);if(password){const action=panel.querySelector('.actions button');if(action)action.textContent='Sign In';panel.querySelectorAll(':scope>.authnote,:scope>form+p.small').forEach(note=>note.remove());panel.querySelectorAll('.tabs button').forEach(button=>{if(/^log in$|^sign in$/i.test(button.textContent.trim()))button.textContent='Sign In'})}}
